window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["5398985"]={"book":{"id":5398985,"title":"积极情绪的力量","author":"【美】芭芭拉•弗雷德里克森","translator":"王珺/阳志平校","publisher":"中国人民大学出版社","pubdate":"2010-12","isbn":"9787300129495","tags":["积极心理学","心理学","情绪","心理","励志","心智","思维","积极情绪的力量"],"memCount":5},"np":1,"pb":[10],"idx":[{"i":18780,"t":"在日常生活中，无论是与家人朋友还是同事，我们都可能因为某些行为或言语伤害到他人。道歉是修复关系的重要方式，但并不是所有的","l":"TF1-1","c":"此念","g":1,"p":1},{"i":17550,"t":"打破思维反刍的桎梏","l":"TF1-1","c":"银河丫丫","g":1,"p":1},{"i":15849,"t":"积极情绪","l":"TF2-4","c":"青橙可乐TOYO","g":1,"p":1},{"i":10697,"t":"正确道歉四步法","l":"TF2-3","c":"阿静","g":1,"p":1},{"i":9001,"t":"制作属于自己的积极情绪档案","l":"TF1-1","c":"卷毛小蓝","g":0,"p":1},{"i":6103,"t":"拆除消极情绪地雷，减少消极情绪；品味美好，增加积极情绪。","l":"TF2-4","c":"jiafeimao","g":1,"p":1},{"i":5073,"t":"积极情绪的力量","l":"TF3-3","c":"龚陟","g":1,"p":1},{"i":4739,"t":"给予关注并积极回应","l":"TF1-1","c":"船长（魏云）","g":1,"p":1},{"i":2131,"t":"怎么体会积极的情绪","l":"TF1-1","c":"上善若水","g":0,"p":1},{"i":666,"t":"觉知力、主动行善","l":"TF3-3","c":"向军","g":1,"p":1}],"ms":[{"id":18780,"topic":"在日常生活中，无论是与家人朋友还是同事，我们都可能因为某些行为或言语伤害到他人。道歉是修复关系的重要方式，但并不是所有的道歉都能真正起到作用。当你向他人表示歉意时，请记住3个步骤： 想知道是哪三个步骤，请来参加我的拆书课吧！","learn_goal":"","remark":"在日常生活中，无论是与家人朋友还是同事，我们都可能因为某些行为或言语伤害到他人。道歉是修复关系的重要方式，但并不是所有的道歉都能真正起到作用。当你向他人表示歉意时，请记住3个步骤：\n想知道是哪三个步骤，请来参加我的拆书课吧！","level":"TF1-1","duration":30,"status":30,"type":0,"chaishujia":{"username":"此念","city":"宁波市"},"club":{"name":"宁波幸福虚度分舵","city":"宁波"},"prologue":"\u003cp>\u003cstrong>自我介绍：\u003c/strong>\u003c/p>\u003cp>大家好，感谢你们来参加我的过级观察。我来自浙江玉环，古志记载：“晨雾绕岛，形状如环；上有流水，洁白如玉”，这就是我家乡名字的由来。接下来介绍一下我自己吧。我微信名“此念”，在心理学领域意为“当下”，来日并不方长，当下即是最好。大名周爱霞，“爱”即热爱喜爱，“霞”指彩霞，寓意对美好的向往追求。\u003c/p>\u003cp>我的三个标签：创业者，婚姻家庭辅导师，独抚妈妈。生活投之以痛我却报之以歌，相信人生走过的每一步都算数。喜欢认识有趣的灵魂，一直信奉“人无癖不可交，以其无深情也”，希望在拆书帮不但能提升能力，还能认识志同道合的小伙伴们。\u003c/p>\u003cp>\u003cstrong>拆书帮介绍\u003c/strong>\u003c/p>\u003cp>第一次听到“拆书”这个词，我打了个问号？什么是拆书？拆书可不是字面上的意思，把书拆掉，“拆”是转化的意思，就是把书里的知识转化为自己的能力，为我所用。大家有没有这样的感触，就是我们参加了很多的培训课，也给自己制定了学习计划并且去执行了，但是一年下来，发现自己真正落到实处的能力并没有提升，也就是说你学的和你做的并不能融会贯通，这样的学习我们总结为以知识为中心，你貌似学了知识，但它在实际中并不能解决问题。而拆书法适用以“我”为中心而不是以知识为中心的成人学习，“我”就是学习者，强调要把书里的知识跟学习者的经验和计划紧密结合，活学活用现学现用，不论你选哪类书，目标都是致用，也就是“拆为己用”。\u003c/p>\u003cp>拆书法分为个人学习法和组织学习法。个人学习的拆书法，主要是为了改变学习者的行为习惯、提升自身能力、解决实际问题，也叫“RIA便签学习法”：R是阅读原文片段，I是用自己的语言来复述这个片段，这个过程会把知识内化为自己的语言。A1需要结合自己的经验和片段相关联，A2是对未来做目标规划。组织学习的拆书法，是指通过拆书家现场拆解一本书的片段，引导来参加的学习者群体如何学会把知识拆为己用，也叫“RIA现场学习法”。\u003c/p>\u003cp>拆书帮成立于2013年4月6日，距今已有12年了。它是基于一群志同道合的拆书爱好者的社群，在全国各地都设立了分舵，也可以称作“拆书俱乐部”，是非营利性的青年自组织。\u003c/p>\u003cp>拆书帮的愿景是通过拆书家的能力提升去帮助影响身边更多的人。\u003c/p>\u003cp>拆书帮的使命是帮助更多学习爱好者成长为拆书家。\u003c/p>\u003cp>\u003cstrong>过渡语\u003c/strong>\u003c/p>\u003cp>那现在就由我来带领大家拆解一下今天的片段。下面我们花2分钟时间看一下原文片段，看完后抬头示意一下。\u003c/p>","ratings_count":1,"texts":[{"id":23103,"quote":"\u003cp>\u003cstrong>【R】阅读原书拆页\u003c/strong>\u003c/p>\u003cp>选择书籍：《情绪的力量》\u003c/p>\u003cp>【R阅读原文拆页】第六章P274-275页\u003c/p>\u003cp>主题：当你向他人表示歉意时，请记住3个步骤。\u003c/p>\u003cp>1.承认自己的错误。记得压制自己解释的冲动——不然你会显得很有戒心，甚至会让人觉得你已经开始找借口开脱了。如果你想说明情况，首先要明确自己为行为担责的态度，例如，“我确实打断你说话了。前一天晚上睡得不好，不过这也不能作为我行为不得体的借口”。而且一定要具体！汤姆建议：“具体的描述能够让对方知道你理解他们谈话的来由。”最后，诚恳面对对方的感受。你可以说：“我之前不知道你觉得我发的邮件简单粗暴。谢谢你告诉我。” 2.说“对不起”。有太多的“道歉”缺少一句明确的致歉语。另外，“对不起”这个句子只应该有3个字。一旦加上“如果我粗鲁的行为让你感到不舒服”，这句“对不起”就立马显得非常虚伪了。不要在道歉中暗示对方过于敏感，要为自己的错误承担责任。 3.表明这类情况不会再次发生。告知对方你的行为将会有什么改变，避免同类错误的出现。\u003c/p>","explains":"\u003cp>\u003cstrong>分享I便签\u003c/strong>\u003c/p>\u003cp>在日常生活中，无论是与家人、朋友还是同事，我们都可能因为某些行为或言语而伤害到他人。道歉是修复关系的重要方式，但并不是所有的道歉都能真正起到作用。《情绪的力量》中提到的“道歉三步骤”为我们提供了一个清晰而有效的框架，帮助我们在道歉时更真诚、更有说服力。\u003c/p>\u003cp>第一步：承认错误\u003c/p>\u003cp>道歉的第一步是承认自己的错误，而不是试图为自己辩解或推卸责任。这一步的核心是真诚地面对自己的行为，并明确指出自己哪里做错了。例如，因为你工作上的疏忽导致团队项目延误，你可以这样说：“我在项目中没有及时完成自己的部分，这导致了整个团队的进度被拖延，这是我的责任。” \u003c/p>\u003cp>承认错误的关键在于具体化，清楚地说明“哪里做错了”。这不仅让对方感受到你的诚意，也表明你对自己的行为有清晰的认知。\u003c/p>\u003cp>第二步：表达歉意\u003c/p>\u003cp>在承认错误之后，接下来是表达歉意。这一步看似简单，但实际上非常重要。你需要用真诚的语言向对方表达你的歉意，并说明你对对方的感受的理解。例如，你可以说：“我真的很抱歉因为我的疏忽让你感到失望，我知道这对你来说是一个很大的困扰，我感到非常内疚。” \u003c/p>\u003cp>表达歉意时，不要使用敷衍的语气，比如“对不起，我不是故意的”，而是要让对方感受到你的真心。\u003c/p>\u003cp>第三步：承诺改进\u003c/p>\u003cp>在道歉的第三步中，核心是向对方表明类似的问题不会再次发生。具体来说，你需要明确指出你将如何改变自己的行为，避免同类错误的出现。比如，如果你因为忘记约定而让对方失望，你可以承诺：“为了避免类似情况再次发生，我会在日程中设置提醒，并提前一天确认计划。”这种具体的承诺不仅能让对方感受到你的责任感，也能帮助你真正从错误中吸取教训。\u003c/p>\u003cp>需要应用到道歉三步骤的场景很多，比如重要的商务聚餐迟到，没有完成有时间要求的项目进度，和孩子的承诺没有兑现等，而在公共场所不小心碰撞到对方只需要一句“对不起”就可以了。\u003c/p>","interaction":"\u003cp>\u003cstrong>分享A1便签\u003c/strong>\u003c/p>\u003cp>上周四下午，我女儿因为腰疼让我跟班主任请假要去针灸，我答应了，结果因为各种琐事一忙碌就给忘了。我女儿找班主任签请假条的时候才知道我压根没和老师说过请假的事，结果她假没请成，腰又一直痛。夜自修结束回来一脸不高兴，我还没想起来发生了什么，她就哭了。在我一再的追问下，才说自己被老师误解觉得很难堪，恨死我了。我和她说：对不起，都是老妈的错，向你道歉。但是她不接受，认为我根本不在意她，没把她的需求放在心里。我和她解释说有时候事情忙忘了也很正常，没必要搞得这么严重吧，我都向你道歉了，你也体谅一下老妈。结果这话一出，直接把问题严重化了，孩子一边哭一边喊：你自己没做到的事情还拿我不体谅你来道德绑架，反正你做大人的就对，你这个态度也叫道歉吗？最后她把门砰地一关，就不理我了。就这么点事，结果却不欢而散。\u003c/p>\u003cp>学了道歉三步骤后，我认识到我当时的道歉是为了息事宁人，并没有发自内心地认为自己有错，只是为了让这件事早点翻篇，反而更激发了矛盾。所以这不是一个合格的道歉。第二步，我向女儿道歉是敷衍的，没有让她感受到她的委屈是被理解的，而是在解释自己不是故意的。第三步，我也没有表达为了不让类似问题发生，我应该具体用什么行动来表示，从而让孩子看不到你的诚意。\u003c/p>\u003cp>\u003cstrong>分享A2便签\u003c/strong>\u003c/p>\u003cp>4月份我可能因女儿未及时丢房间垃圾的事情而直接指责她，如果发生这样的情况，我和女儿约定，她可以在反馈本上提醒我，我会针对此种情形进行道歉。\u003c/p>\u003cp>第一步，真心认错，不找理由。“错误”反馈法：准备笔记本，我用红笔写上：今天我不应该因为房间的垃圾吼你。孩子用蓝笔回复：我当时想着出门前收拾，顺便带出去的，你这一吼，我就不想做了。我：因为我没有及时沟通上来就责怪，方式方法简单粗暴，确实容易伤害别人。\u003c/p>\u003cp>第二步，真诚道歉，表达理解：老妈应该在看到垃圾后先和你沟通，是不是忘了扔垃圾还是什么原因，这样就知道你其实是打算出门前去扔的，就不会误会你了。这样不分青红皂白就批评你是我的错，希望你能原谅老妈的不当做法。\u003c/p>\u003cp>第三步，表明态度，不会再犯：我在桌面、床头、门口贴上标签：心平气和和颜悦色地说话，每天早上晚上都念一遍。如果一周中有3次没有做到，可以请你吃一顿海底捞作为弥补。制定家庭关系修复日：约定每月15日为家庭关系修复日。有什么问题和委屈都记在错误反馈本上，到15日的时候做一次深度交流和真诚的道歉。\u003c/p>\u003cp>\u003cstrong>结束语\u003c/strong>\u003c/p>\u003cp>道歉不是认输。最管用的话往往是能够真诚反映你认识错误、理解对方感受、并承诺改变的话语。道歉不仅是对过去的弥补，更是对未来关系的投资。通过真诚的沟通理解和共鸣，大多数误会与冲突都可以找到解决之道，让关系更加坚固。\u003c/p>\u003cp>通过这次关于道歉三步骤的拆解，希望我们在碰到问题需要道歉的时候，也能很好的运用道歉三步骤。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1744168873000,"updated_at":1744177358000,"ria":true},{"id":17550,"topic":"打破思维反刍的桎梏","learn_goal":"","remark":"过度担忧和反复思考是导致积极情绪下降的主要原因,这种反复思考会使消极情绪加剧，进而导致全面的焦虑。打破思维反刍的桎梏，需要采用科学验证的方法。其中，最重要的是认识到思维反刍是一种恶性循环，其次，采取科学有效的方法----有益健康的分心。通过认识到何时思维陷入困境，并创造一些分心的活动，进而提升积极情绪，强化内在动力。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"银河丫丫","city":"常州市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>各位拆书家、准拆书家伙伴们，大家晚上好，我叫王艳玉，网名YY，来自风景如画的常州！今晚，我想用三个有趣的标签来展示我的多彩人生。首先，我是一个“社区魔法师”，悄悄地在党建和妇女儿童工作中施展魔法，让社区充满爱与和谐。在疫情期间，我化身为“抗疫英雄”，带领志愿者们守护家园，因此荣获常州市疫情防控先进工作者称号。其次，我是家里那个“超级英雄”的“幕后军师”。在与孩子斗智斗勇的日子里，我不断挑战自己的智慧与耐心，陪伴孩子，共同成长。最后，作为一名资深长跑爱好者，已累计完成4900公里跑步里程，并成功参与了三次半马比赛。跑步，是实现自我对话的一种方式。这就是我，多面又独特的YY！下面为大家介绍“拆书”和“拆书帮”。“拆书”是一种学习方法论，适用于以提升能力、解决问题为导向的成人学习，它强调以学习者为中心而不是以知识本身为中心，旨在把具体知识关联学习者的过往经验并规划具体运用。“拆书”分为个人学习的拆书法和组织学习的拆书法；个人学习的应用称为RIA便签法，它的效果等同于让人读一本书就能达到参加一场同主题培训的效果；组织学习的应用是一位拆书家拿一本书中一个片段加工出一场现场学习，引导并且促进一群人把知识拆为己用。如果从学习者的学习效果来衡量的话，一位拆书家创造的价值不亚于一位培训师。“拆书帮”是基于拆书法的学习爱好者社群，表现为各地的拆书帮分舵（也叫拆书帮俱乐部），拆书帮分舵是非营利性青年自组织，其使命是帮助更多学习爱好者成长为拆书家。\u003c/p>","ratings_count":2,"texts":[{"id":21737,"quote":"\u003cp>片段来源：《积极情绪的力量》 【P161-P162】\u003c/p>\u003cp>作者：【美】芭芭拉•弗雷德里克森\u003c/p>\u003cp>出版社：中国人民大学出版社\u003c/p>\u003cp>主题：打破思维反刍的桎梏\u003c/p>\u003cp>对问题无休止的担忧和思维反刍，是使你的积极率一落千丈的一个重要原因。它让你的消极情绪翻倍，而且适用于所有的消极情绪。一开始你有点担心，然后思维反刍，于是你的担心导致全面的焦虑发作扩大。先有一点点悲伤，加上思维反刍，于是你产生了抑郁症的症状。愤怒也一样，经历了挫折，在内心大声叫嚷，于是你很可能用暴力来解决问题，或是在言语上带着一股火药味儿。由于有真实的消极情绪做引子，思维反刍会创造出像鼠穴一样不断蔓延的无端的消极情绪，强占你的心理空间。\u003c/p>\u003cp>思维反刍几乎不给你任何立场来反驳消极思维。毕竟，审视你的现实情况是需要有清晰的思维的。在你能对所面临的情况清醒地思考之前，你需要踩下紧紧包围你的恶性循环的刹车。你需要打破思维反刍的桎梏。幸运的是，有一些经过科学检验的方法可以帮助你做到这一点。这些也同样是认知行为治疗的丰厚遗产的一部分，而这一次的重点放在行为方面。\u003c/p>\u003cp>和许多事情一样，第一步是认识。你要能够在思维反刍发生的时候，发现那个恶性的循环。你必须认识到你的无休止苦思并不能给你带来任何好处。只有这时，你才能选择做一些完全不同的事情。\u003c/p>\u003cp>看起来最有帮助的，是有益健康的分心。做一些确实让你将思维从麻烦中转开的事情：慢跑，在大海中游泳，修理你的自行车，在体育馆举重，冥想或做瑜伽。无论如何，找到一个能让你完全投入的活动。也许，你可以给你的朋友打电话，问问他最近的旅游经历；或者，你可以阅读那些你一直都想读的文章；或者摆弄你的新手机。\u003c/p>\u003cp>你需要做的是提升你的情绪。当然，如果能找到一个你所喜爱的活动，也会很有帮助，这不仅把你的心情从水沟里捞起来，而且还为你带来欢乐、迷恋或自豪。然而，分心也可以是中性的。只要能让你摆脱思维反刍——从顾虑过多中脱身——它们就符合要求。相当中性的活动可以打破思维反刍，并让你走出恶性循环。然后一旦你走出了消极情绪的下斜坡，你就有足够明亮的眼睛去反驳消极思维，并解决你所面对的任何问题。\u003c/p>\u003cp>你可能已经注意到，我说的是健康的分心。并非所有的分心都对你有好处。许多人试图用酒精或药物来麻痹他们的思维反刍。事实上，高度倾向于思维反刍的人，也有更高的酗酒风险。食物能成为另一种不健康的分心。有些人用食物来逃避痛苦的自我意识，这可能会导致暴食和其他情绪性进食的问题。而且，正如我将在这一章稍后部分讨论到的，沉溺于电视媒体也能够引发各种问题。例如，许多电视节目尽管吸引人，但也包含了大量的暴力内容。如果以这种形式来干扰你的消极情绪，等你将视线从屏幕上抬起来时，你的情绪状况往往更糟。同样的结果也可能发生在将你的iPod音乐播放器存满悲伤的歌曲时。认识到使用酒精、食物或媒体等手段来逃脱思维反刍是不可取的，可以帮助你选择更健康的分心形式。\u003c/p>\u003cp>慢慢认识到你的思维在什么时候走投无路，创造一个帮助你分心的活动的库房，以便你打破思维反刍的桎梏，并提升你的积极情绪。\u003c/p>","explains":"\u003cp>这个片段讲的是什么呢？讲的是对既成事实的问题进行无休止的忧虑和思维反刍，极易引发心理问题。我们应当认识到这一问题的严重性，并通过科学、有效的行动，妥善应对并做出相应调整，积极维护身心健康。为什么要及时发现并阻止思维反刍呢？思维反刍让消极情绪翻倍，导致全面的焦虑发作扩大，会使人产生抑郁症的症状，或者表现为愤怒，于是很可能用暴力来解决问题，导致人际关系紧张甚至破裂。同时，思维反刍会创造出像鼠穴一样不断蔓延的无端的消极情绪，强占心理空间，对身心健康极为不利。怎样改善这一状况呢？我们需要打破这种反复思考的惯性。第一步培养自我意识，当思维反刍发生时，必须能够快速识别出这种恶性循环并立即中断它；第二步提升情绪状态，我们应积极寻找一个能触发全身心投入的分心手段，通过调整模式，如跑步、阅读、练习瑜伽、聆听音乐以及整理房间等，我们能够更加有效地调节自身的情绪状态，实现情感状态的优化。最后，此方法适用于职场人际关系、亲子交流、家庭成员间矛盾、以及与陌生人产生摩擦等导致的负面情绪，增加自身抵抗熵增的能力。\u003c/p>","interaction":"\u003cp>A1:前段时间，因为有个同事离职了，她的许多任务转到我这里，我本来就已经挺忙的了，再加上这些额外的工作，真让人头疼。而且，跟领导的沟通也出了点问题，心里特别不舒服。回到家，这些事情一直在脑海里盘旋，还担心孩子的升学问题，感觉压力真的很大，特别是跟领导的对话，一直在脑海里重复，心情就变得更差了。那段时间，我吃得多，睡得少，焦虑的不行。就在我快要撑不住的时候，我读了《积极情绪的力量》这本书，其中“打破思维反刍的桎梏”这部分让我意识到这是陷入了思维反刍的陷阱，这种情绪消耗给我的生活和工作带来了恶性循环。于是，我决定要调整自己的心态和行为模式。面对工作压力和人际关系的困扰，我首先让自己冷静下来，理清思路。我制定了一个合理的工作计划，把任务分解成小块，一步一步地去完成，不急于求成。同时，我也开始关心自己的身体健康，保持良好的作息。对于跟领导的不愉快，我决定主动沟通，坦诚地表达自己的想法和立场，同时倾听领导的意见和建议。通过有效沟通，工作关系也得到了改善。渐渐地，我的心情变得平静。经过对自身状态的及时调整，我发现工作效率提高了，压力也减轻了。至于孩子的升学问题，通过深入了解升学政策和学校情况，结合孩子的实际，我觉得选择适合他的学校才是目前最重要的。\u003c/p>\u003cp>A2:人生的道路上，不如意之事十有八九，这是无法避免的事实。然而，面对挫折和困难，我们如何调整自己的心态，积极应对，就显得尤为重要。在这方面，我认为有两大关键策略需要实践。\u003c/p>\u003cp>首先，提升自己的认知和底层思维逻辑是避免消极情绪滋生的根本之道。认知是指我们对世界的理解和看法，而底层思维逻辑则是我们思考问题的基本方式。一个健康的认知和清晰的思维逻辑能够帮助我们正确看待生活中的挫折和困难，不被情绪所左右。当遇到工作上的挑战时，一个健康的认知会让我们明白这是一个学习和成长的机会，而不是一场灾难。同时，清晰的思维逻辑会让我冷静分析问题的本质，找到解决问题的最佳路径。因此，通过不断学习和思考，提升自己的认知和底层思维逻辑，是在面对不如意之事时，避免陷入消极情绪的关键因素。\u003c/p>\u003cp>其次，找到分心活动的库房，让自己的兴趣爱好成为生活的避难所。当我们在惯性反刍思维中徘徊时，很容易陷入无尽的痛苦和焦虑之中。此时，及时寻找一些能够分散注意力的活动，比如阅读、写作、运动等，能够帮助我暂时脱离困境，给予我心灵的支撑。\u003c/p>\u003cp>在结束之际，我想引用一句古人的智慧结晶：“天将降大任于斯人也，必先苦其心志，劳其筋骨，饿其体肤，空乏其身。”这句话深刻阐述了生活中挫折与困难对于个人成长的必要性。因此，我们应当以积极的心态去面对生活中的种种不如意，不断磨砺自己的认知和思维方式，发掘并培养自己的兴趣爱好，以坚定的步伐迎接未来的挑战。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1714313430000,"updated_at":1714354212000,"ria":true},{"id":15849,"topic":"积极情绪","learn_goal":"","remark":"积极情绪","level":"TF2-4","duration":50,"status":30,"type":0,"chaishujia":{"username":"青橙可乐TOYO","city":"烟台市"},"club":{"name":"烟台八仙过海分舵","city":"烟台"},"prologue":"\u003ch2>自我介绍/1分钟\u003c/h2>\u003cp>大家下午好，欢迎大家来到烟台八仙过海分舵的活动现场，我们即将在这里度过一个充实的下午！\u003c/p>\u003cp>先做个自我介绍，我是本次参加2-4过级的拆书家陈鲁青，三个标签介绍自己：\u003c/p>\u003cp>① 我是一个幸福的二宝妈，我有一对可爱的宝贝儿。\u003c/p>\u003cp>② 我是一个敬业的职场人，我管理着一家出口生产企业。\u003c/p>\u003cp>③ 我是一个快乐的读书人，我每天都享受着阅读和成长带来的快乐。\u003c/p>\u003cp>因为今天现场会有讨论以及演练的环节，所以我们提前做一个分组。\u003c/p>\u003cp>那我们正式开始今天的拆书：\u003c/p>\u003ch2>图书介绍/2分钟\u003c/h2>\u003cp>【F】今天我们拆解的书是《积极情绪的力量》，作者是美国心理学家芭芭拉·弗雷德里克森。这本书第一部分通过大量的研究证据说明了积极情绪在个人发展、成功和幸福生活方面的强大力量。第二部分提供了很多实用的的技巧与方法，来帮助大家管理负面情绪和提高积极情绪。\u003c/p>\u003cp>【A】从封面可以看到，芭芭拉是积极心理学的领军人物，被积极心理学之父马丁·塞利格曼盛赞为“积极心理学领域的天才”，所以她是这个目前这个领域中最顶级、最权威的专家。和其他书相比较，这本书的专业性不言而喻。\u003c/p>\u003cp>这虽然是一本讲积极情绪的书，但作者也对消极情绪进行了适当的解释。作者指出积极与消极是并存于生活中的，重要的是理解它们的成因并学会转换与利用。这让这本书的内容和其他同类型书籍想比更加平衡客观。\u003c/p>\u003cp>【B】我们生活在一个充满挑战的时代，疫情改变了我们生活的方方面面，现在AI又以迅雷不及掩耳之势扑面而来。全球民意调查显示，许多人的幸福感都在直线下降，悲观和失业如乌云般笼罩着我们。在这个困难的时期，培养真正积极的能力是一项至关重要的生活技能，我们要不断强化这个技能，以恢复和提高自己与周围人的幸福感。\u003c/p>\u003ch2>学习目标\u003c/h2>\u003cp>（总目标）今天我们会有两个片段。\u003c/p>\u003cp>第一个片段让大家了解一种方法，叫做“反驳消极思维”，当我们在陷入消极思维的恶性循环时，可以用这个方法去做调整和改善。\u003c/p>\u003cp>但相比减少消极情绪，更理想的是培养积极的思维模式和情绪体验。积极的心理素质可以从根本上影响一个人看待周遭世界的方式。所以第二个片段，我们会学习一个增加积极情绪的方法——品味美好。（递进关系）\u003c/p>\u003cp>（拆页1目标）通过第一个片段的学习，大家可以了解一种方法，叫做“反驳消极思维”，当我们在陷入消极思维的恶性循环时，可以用这个方法去做调整和改善。并且在现场实践环节中大家可以尝试应用，化解之前的一次情绪问题。\u003c/p>","ratings_count":1,"texts":[{"id":19926,"quote":"\u003cp>现在请大家用2分钟的时间阅读一下第一个片段。看完的小伙伴可以抬头给我一个示意。\u003c/p>\u003cp>《积极情绪的力量》，作者：芭芭拉·弗雷德里克森，P160\u003c/p>\u003cp>\u003cstrong>减少消极情绪——反驳消极思维\u003c/strong>\u003c/p>\u003cp>\u003cstrong>失控的消极想法 \u003c/strong>————————————————————————\u003c/p>\u003cp>这是糟糕的一周。已经是星期三了，我已经在电脑前坐了一个又一个小时，但是自周一以后，我还没能挤出4页。我要怎么完成这一章？为了处理丈夫的意外住院，我失去了5月份的写作时间，这样就不能按计划在夏季的几个月里写完这本书了。接下来，就要在秋季学期努力完成它，然而到那个时候我会有太多的事情要忙：我要教学，开始两个新的大型研究项目，指导研究生，主持一个又一个学术会议。等到要努力应付这一切的时候，我永远也无法完成这本书。我有一个朋友，刚刚花了23年完成一本书！天哪，现在我知道这种情况是怎么发生的了。当经纪人和编辑发现我的进程有多么滞后的时候，他们会后悔同意与我合作。他们会发现，当我向他们推荐这本书的时候，我只是在夸夸其谈。只要想到我已经变得多么失败，我的喉咙就越来越僵硬，胃痛，手指几乎没有力量来打出字。我今天毫无进展。为什么不就此放弃？\u003c/p>\u003cp>————————————————————— POSITIVITY ————\u003c/p>\u003cp> 你有过这样的日子吗？没有赶上最后期限或达到你为自己设定的且标。这也许是一个工作目标，就像我的一样；或者，这也许是一个个人目标，比如买回列在清单上的全部食品，以便你能够为家人烹制一顿家常美餐；或者，也许你踏上体重秤，发现自己长了5公斤。无论发生什么原非本意、出乎意料的事件，消极情绪都能很快地失控，使你焦虑或抑郁。\u003c/p>\u003cp> 在20世纪，心理学科学最大的进步也许是破解了一种可预测的模式，即消极思维如何滋生消极情绪，以至于恶性地发展成诸如临床抑郁症、恐惧症和强迫症的病理性状态。消极情绪，如恐惧和愤怒也可以孕育消极的想法。这种交互动态过程，实际上就是恶性循环如此棘手的原因。消极的思维和消极的情绪相辅相成，当它们运行时，你就被拉入了它们的深渊。\u003c/p>\u003cp> 要阻止这种消磨生命的循环，一个方法就是反驳消极思维。通过审查事实，像一名好的律师那样来进行反驳。现在回到我自己的恶性循环。是什么启动了它？是哪些消极思维和信念被触发了？那些思维和信念使我感受到什么？那些思维和信念与现实情况相比又如何？我的情况事实上是什么样的？当我真正纳入那些事实的时候，我感觉如何？\u003c/p>","explains":"\u003cp>好，时间到，看到伙伴们都已经抬起头了。我们一起来看一下这个片段的内容。\u003c/p>\u003cp>Why：我们知道，消极思维可以导致消极情绪，而它们之间会相互促进，一旦启动就会加速恶化，使人变得焦虑、抑郁，形成一个恶性循环。\u003c/p>\u003cp>What：这个片段给到我们打破这种恶性循环的一个方法，叫反驳消极思维，通过审视自己的这些消极思维，然后引入更加客观的事实，找到它们与实际情况的差异，就可以跳出这个恶性循环。\u003c/p>\u003cp>How（细化步骤）：\u003c/p>\u003cp>那具体应该怎么做呢？我们来看一下：\u003c/p>\u003cp>1. 暂停并深呼吸。当觉察到自己已经陷入了消极思维中时，首先需要马上停下来，做几个深呼吸，让自己稍微冷静一下，切断这个恶性循环。\u003c/p>\u003cp>2. 识别消极思维。\u003c/p>\u003cp>①是什么事情启动了我的消极情绪呢？\u003c/p>\u003cp>②是哪些消极思维被触发了呢？\u003c/p>\u003cp>③这些思维让我有什么感受呢？\u003c/p>\u003cp>3.客观审视事实。与其简单相信自己的消极推论，更重要的是客观审视相关的事实和证据。看看自己是否存在过度解读或误判。\u003c/p>\u003cp>4. 找到差异。找到消极思维与事实不符的部分，消极情绪会随之改善，它就无法在现实的基础上持续下去。\u003c/p>\u003cp>5. 采取行动。在思维和情绪得到改善后，还需要根据实际情况采取相应的行动。\u003c/p>\u003cp>这就是“反驳消极思维”的5个具体的步骤：\u003c/p>\u003cp>1、暂停并深呼吸。\u003c/p>\u003cp>2、识别消极情绪。\u003c/p>\u003cp> ①是什么事情启动了我的消极情绪呢？\u003c/p>\u003cp> ②是哪些消极思维被触发了呢？\u003c/p>\u003cp> ③这些思维让我有什么感受呢？\u003c/p>\u003cp>3、客观审视事实。\u003c/p>\u003cp>4、找到差异。\u003c/p>\u003cp>5、采取行动。\u003c/p>\u003cp>【异议+不这么做的坏处】\u003c/p>\u003cp>那小伙伴有可能会说了，我在情绪不好的时候，根本就没有办法去跳出那个恶性循环，去做理性的分析，我根本就做不到呀！\u003c/p>\u003cp>那我想你可能还没有意识到这种恶性循环带来的严重影响，当消极思维和消极情绪相互作用、不断加强的时候，就会导致焦虑、自卑等这些更加强烈的消极情绪，这会严重的影响我们的工作和生活的质量。\u003c/p>\u003cp>并且消极的想法还会导致对问题的误判，如果采取的解决方案不当，就会使问题更加的严重，带来更多的损失。\u003c/p>\u003cp>而相反，如果我们愿意去刻意练习使用这个方法，它可以很好的改善我们的情绪状态，增强心理健康和幸福感。\u003c/p>\u003cp>同时理性和客观的思考方式，还可以帮助我们发现问题的真正所在，找到最佳的解决方案。这对于我们在情绪管理、解决问题、建立信心等很多方面都是有很多好处的。\u003c/p>\u003cp>【意译案例】\u003c/p>\u003cp>举个我自己的栗子：\u003c/p>\u003cp>这是一个糟糕的假期，已经是五一小长假的最后一天了，我躺在床上昏昏沉沉的抱着书，翻了一页又一页。5天的假期，我的2-4的拆书稿上还是没有增加几个字。我要怎么能完成我的过级呢？\u003c/p>\u003cp>原本是要在假期中完成拆书稿的，但是因为假期第一天和家人外出游玩，着凉了，我昏昏沉沉的躺了好几天，这个假期几乎没有什么产出。而接下来我就只有10天的准备时间了，然而到那个时候我会有更多的事情要忙，工作上需要准备一个新的订单和样品，下周一会有一个新的训练营要开营，而和孩子们刚刚开启的运动和阅读计划也不能停止。天哪，当假期结束要努力应付这一切的时候，我永远也完不成不了我的拆书稿了。\u003c/p>\u003cp>我有一个朋友，已经7年了还没有通过二级！天哪，现在我知道这种情况是怎么发生的了。当我的师父发现我的进度有这么滞后的时候，她一定会后悔收我这个不上进的徒弟。她会发现每当我信誓旦旦的想要过级的时候，我只是在夸夸其谈，而没有行动。只要想到我已经变得多么失败，我的心就开始崩崩跳的很快，胸口像有一块大石头，头也开始隐隐作痛，根本看不进去书上的字。我今天毫无进展，为什么不就此放弃呢？\u003c/p>\u003cp>（1.暂停并深呼吸）当我发现到自己已经陷入了消极情绪的恶性循环时，我意识到我不能被消极的思维所左右，于是我放下书，闭上眼睛，做了几个深呼吸，让自己的心跳放慢一点。\u003c/p>\u003cp>（2. 识别消极思维）我试着开始去分析。启动我的消极情绪的是整个假期里，我的2-4的拆书稿几乎没有进展，我对自己感到很失望，这触发了我的消极情绪：我觉得我永远也写不出来，我的师父会对我很失望，我是一个失败者。这让我感觉很焦虑、很挫败，同时觉得胸口发闷、头痛。\u003c/p>\u003cp>（3.客观审视事实）那事实是这样的吗？我打开了我的预备表，事实上我已经阅读完了整本书，选择好了片段。并且拆书稿也有了一个大框架，我需要做的就是加入讲解、案例和场景演练的部分，所以相当于已经完成了一半。\u003c/p>\u003cp>然后我又查看了假期后面10天的日程，3天后就有一个周末，我可以和家人协商，把这一整天拿出来，用于完成我的拆书稿。这样我还有一个周的时间，可以每天抽出半小时--一小时用来修改和练习，应该可以赶在预定的日期进行2-4的线下过级。\u003c/p>\u003cp>（4. 找到差异）当我考虑到这些事实以后，我的呼吸变得轻松了，头也不那么疼了，我觉得又充满了希望。不管怎么样，我要在这个周末把第1稿的预备表完成发送给师父。\u003c/p>\u003cp>（5. 采取行动）我马上在我的日清单中把周末的时间预留出来，并且告诉老公，希望他这个周末可以陪伴孩子，给我一整天的时间用来完成拆书稿。\u003c/p>\u003cp>所以这篇拆书稿就是在上周日，用一整天的时间完成的~\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1激活经验】\u003c/strong>各位小伙伴，在过去的一段时间内，你有没有在工作中遇到诸如工作不顺利、业绩下降、被领导责备，从而产生焦虑、自责和无助感的情况？\u003c/p>\u003cp>你有没有在学习中遇到诸如考试失败、论文被驳回、任务完不成，从而对自己的学习能力产生怀疑，觉得前途渺茫的情况？\u003c/p>\u003cp>你有没有在生活中遇到诸如健康问题、经济损失，从而感到恐惧、焦虑的情况呢？\u003c/p>\u003cp>请大家回想一下，可以在资料的第二页中写下关键词，我们大约有1分钟左右的时间，每个小组成员先交流一下，然后请一个小伙伴进行分享。\u003c/p>\u003cp>\u003cstrong>学习者案例分享：\u003c/strong>\u003c/p>\u003cp>代宁：最近在一个企业拆书项目做教练，需要学员每天提交拆书作业，但因为他们是销售，本身工作很忙，虽然我一直在催我们小组成员的作业，但还是没用，看到别的小组100%提交作业，就很挫败，觉得自己不能胜任。\u003c/p>\u003cp>\u003cstrong>【A1反思加工】\u003c/strong>好，假如现在重新回到让我们情绪低落的那一刻，用我们今天所学习的“反驳消极思维”的方法，我们该如何跳出消极情绪呢？\u003c/p>\u003cp>再回顾一下“反驳消极思维”的步骤：\u003c/p>\u003cp>1、暂停并深呼吸。\u003c/p>\u003cp>2、识别消极情绪。\u003c/p>\u003cp>①是什么事情启动了我的消极情绪？\u003c/p>\u003cp>②是哪些消极情绪被触发了？\u003c/p>\u003cp>③这些思维让我有什么感受呢？\u003c/p>\u003cp>3、客观审视事实。\u003c/p>\u003cp>4、找到差异。\u003c/p>\u003cp>5、采取行动。\u003c/p>\u003cp>请大家思考1分钟，可以在纸上写下关键词，然后在小组中进行讨论，然后请一个小伙伴进行分享。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>代宁：如果再次回到这个场景中，按照今天的这个片段步骤：我可以先静下来，然后看看这个消极情绪是哪里来的，因为小组成员不回应我的催促，不交作业。然后再看看事实是不是这样的？经过了解我发现他们并不是不写，而是确实太忙了，没写完。所以我下一次再改善一下方式，我可以让他们提前写，避开忙的时间。\u003c/p>\u003cp>（反馈）好，你看到了事实是他们也是在写，只是没有完成，这个事实和你之前的消极想法是有差异的，因此你采取了行动，避免了这种消极情绪的出现。谢谢你的案例，清晰的呈现了反驳消极思维的步骤。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":19927,"quote":"\u003ch2>衔接+学习目标/1分钟\u003c/h2>\u003cp>刚才的片段我们学习了反驳消极思维，可以使消极情绪减轻，但更理想的是培养积极的思维模式和情绪体验。积极的心理素质可以从根本上影响一个人看待周遭世界的方式。所以接下来，我们要一起来学习一个增加积极情绪的方法——品味美好。（递进关系）\u003c/p>\u003cp>通过这个片段的学习，希望让大家了解一种锦上添花的提高积极情绪的方法，感受到它的美好，并且把它规划应用到之后的生活中去。\u003c/p>\u003cp>下面请大家翻开资料的第3页，用2分钟的时间阅读一下拆页2的内容，阅读完成的伙伴可以抬头给我一个示意。\u003c/p>\u003ch2>【R】阅读原文拆页/2分钟\u003c/h2>\u003cp>《积极情绪的力量》，作者：芭芭拉·弗雷德里克森，P185\u003c/p>\u003cp>\u003cstrong>增加积极情绪——品味美好\u003c/strong>\u003c/p>\u003cp>当有什么好事情将要发生在你的身上时，你会对自己说什么？当你被好运气包围时，你在想什么？或者当某些美好的事物从你后视镜的视野里退去时，你脑海中闪过的是什么？人们的反应各不相同。有些人让怀疑和猜忌带路，“这不会真的发生在我身上”“这是不可能发生的！”，或者“我知道这不会持续太久”。其他人会以这样或那样的方式，不对它多加考虑。美好仿佛突然接近了他们，接着又同样迅速地消失了。然而，有些人找到了品味美好的方法。\u003c/p>\u003cp>无论是在他们的未来、现在或是过去，他们以下面的这种方式来思考它，从而让它延伸、给它打气。在一些好事情发生以前，这些人可能会告诉自己，当……的时候就太美妙了。当这种事情发生的时候，他们可能会想，我真想完全陶醉在其中。然后，在这个事件过后，他们可能会在自己的想象中重演它，重温它带给他们的一切美好感觉。像这样品味的人们，能从生活中汲取更多的积极情绪。\u003c/p>\u003cp>人们是否会自然而然地品味美好，往往是一个关于自尊心的问题，关于他们是否觉得自己“应当得到”好事情在自己身上发生的运气。尽管如此，品味是一种你可以开发的心智习惯。在第5章介绍的我的实验研究，证实了品味的能力是你可以建构的一种资源。除了简单地接受美好，你还可以学会去品尝它、深深地欣赏它的每个方面。如果品味对你来说还很新奇，那么学习去做好它，随着你在愉快事件的前中后期提取出更多由衷的美好，就能使你的积极情绪会提高到三倍。品味只是意味着以这样一种方式来考虑好事情，也就是你有意识地创造、强化并延长你对它们的由衷的享受。\u003c/p>\u003cp>品味需要你放慢脚步并有意识地去关注，这就好像花时间去欣赏准备一顿美餐所包含的各个好的方面，从感受新鲜蔬菜和调料的香气到沉醉于调配作料所带来的成就感。然后，当完全沉浸在与朋友或家人一起分享你的杰作时，你能品味更多。\u003c/p>\u003cp>但是请记住，品味不是分析。提高积极情绪要求轻微的心理碰触，把经验作为一个整体来接受，欣赏它带给你的感觉。不要解剖它或是以其他方式把它扯开。回想一下那些证明了过度分析会打击积极情绪的实验。\u003c/p>","explains":"\u003cp>What：这个片段给我们提供了提高积极情绪的另一个策略——从好事情中寻找好的方面，将积极的事物变得更加积极。\u003c/p>\u003cp>Why：不知道你有没有这样的感受，当我们匆匆忙忙从一个景点奔赴到另外一个景点，完成一次旅游之后，我们并没有感受到轻松和享受，也没有留下太多的回忆。\u003c/p>\u003cp>当我们吃饭的时候，我们可能在看手机，或者聊天，根本没有在意食物的味道，也体会不到美食所带来的满足感。\u003c/p>\u003cp>当我们匆匆读完一本书，拿起另一本书，却没有深入的思考，最终也没有什么真正的领会和收获。\u003c/p>\u003cp>总之如果不能够静下心来细细的品味，我们容易错失生活中许许多多的美好时刻，无法从中获得最大的幸福感。\u003c/p>\u003cp>而如果我们能用片段中的方法，在事前憧憬，事中享受，事后重温，就能让我们的积极情绪提高3倍，让生活变得更有味道。学会在生活中预期美好、沉浸其中与回味，这些美好时刻才会成为你人生中的瑰宝，而不仅仅是一个过眼云烟。 \u003c/p>\u003cp>How：\u003c/p>\u003cp>我们一起来看一下，要如何去做：\u003c/p>\u003cp>1. 预期美好。在好事发生前，告诉自己“这会很美妙”。通过预期，可以提高体验美好的准备度和兴奋感。\u003c/p>\u003cp>2. 沉浸其中。当好事发生时，完全沉浸于其中，用心感受每个方面。慢下来，敞开心扉，全身心投入，如同享受一顿美餐的各个过程。\u003c/p>\u003cp>3. 回味回顾。在事件过后，回顾并重温它带给你的美好感觉。这可以延长积极情绪，让正能量持续更长时间。\u003c/p>\u003cp>【异议+不这么做的坏处】\u003c/p>\u003cp>可能有的人会说，这太麻烦了，我有很多事情要做，哪能在一件事情上花费这么多时间！\u003c/p>\u003cp>是的，大家已经习惯了生活节奏的快速，不愿意放慢脚步去体会生活的细微之处。但是要知道，快速生活的代价是容易错失许多美好时刻。尝试着放慢生活节奏，用心去品味每个美好的瞬间，这会让你的人生更加充实和愉快。\u003c/p>\u003cp>【举例】\u003c/p>\u003cp>去年我的生日，老公送给我一块红色的手表，非常漂亮，晚上又给我准备了生日晚宴，还邀请了一些朋友同事来给我过生日。但我其实比较内向，不是很喜欢人多的场合，这种宴请会让我比较有压力，一整天都有点紧张。\u003c/p>\u003cp>在晚宴开始之前，我就各种忙着点餐、安排位置，招待朋友同事，接受她们的礼物祝福等等。在这个过程中，孩子们也很开心，和小客人们闹成一团。我正和一个朋友说着话，突然我儿子很兴奋的跳过来，冲着我就是一拳，我下意识的伸手去挡，结果他这一拳正好打在我的新手表上，把穿表带的轴突打断了。我当时真是非常恼火，但那个时候又不好发作，只好强压着情绪，焦头烂额的应付各种琐事。整个晚上也没有真正放松下来，享受和朋友在一起的时刻。一天结束之后，我感受到的是疲倦，而非愉悦。\u003c/p>\u003cp>后来当朋友问我生日的感受时，我也只能礼貌的说，挺好的，谢谢你们来参加我的生日宴会。但是其实我根本没有全身心的感受到家人朋友的祝福和用心。\u003c/p>\u003cp>【反例变正例】\u003c/p>\u003cp>后来我读了这本书，知道了这个方法之后，我就决定要过一个美好的生日。\u003c/p>\u003cp>1. 预期美好。在生日的前一天，我就告诉自己我将会度过一个美妙的生日，我为自己预定了一款叫做“花样年华”的蛋糕，我感觉自己就是在像花一样美好的年纪，我很珍惜现在的时光，于是我就已经很期待着这个美好的日子的来临了。\u003c/p>\u003cp>2. 沉浸其中。这一次，我们没有邀请朋友同事，而是在家里一家人聚在一起，儿子给我插蜡烛、点蜡烛，女儿就忍不住已经在一边偷偷用手指抹奶油了，我并没有生气，而是微笑的看着她偷吃时的可爱表情。然后老公关上灯，孩子们给我唱生日快乐歌，儿子唱的很大声，先唱了一遍中文的，又唱了一遍英文的。我闭上眼睛许愿，女儿在旁边催促我，好了没有？我说别急别急，我有三个愿望呢~我在心中默默的将我的三个年目标实现的场景都想象了一遍，然后我们一起吹灭了蜡烛，开始分享蛋糕。虽然我在减重阶段，不宜吃这种甜品，但是在这样一个时刻，谁还会去在乎这些热量呢？我能感受到的是一家人温暖的陪伴，一脸笑容的老公，以及可爱的孩子们，他们就是我幸福的源泉。\u003c/p>\u003cp>3. 回味回顾。晚上睡前，我感谢老公，亲吻了孩子们让我度过了一个非常非常愉快的生日，当我闭上眼睛回顾这一天，我感觉到内心充满了平静，温暖和幸福。\u003c/p>","interaction":"\u003ch2>【A3】促动参与/15分钟\u003c/h2>\u003cp>\u003cstrong>情景：\u003c/strong>\u003c/p>\u003cp>这样的感觉是不是特别美好呢？请大家翻到资料的下一页，这里我给到大家一个情景，请大家运用这个方法来感受一下。\u003c/p>\u003cp>下周三（5月17日）即将上映《速度与激情10》，作为《速度与激情》系列电影粉丝的你，计划在周末的晚上和朋友（或者同事、家人）一起去观看这部大片。\u003c/p>\u003cp>作为观影的搭档，请大家两两一组来尝试一下这个品味的过程。运用品味美好的步骤：预期美好、沉浸其中、品味回顾，演绎观影前、观影中和观影后的三段对话。我们有用10分钟的时间来进行思考和演练，然后我们会请一组小伙伴来给大家角色扮演。\u003c/p>\u003cp>指令：现在让我们请一组伙伴来进行角色扮演，扮演一起去观影的同伴，可以是朋友关系、同事关系，或者家人。运用品味美好的步骤：预期美好、沉浸其中、品味回顾，来演绎观影前、观影中和观影后的三段对话。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>【观影前】：\u003c/p>\u003cp>兰兰：听说下周三上映《速度与激情10》了，你有没有什么想法？\u003c/p>\u003cp>大辉：我已经买好了零点票，就等着去\u003c/p>\u003cp>兰兰：这个电影有什么好的，值得你不睡觉去？\u003c/p>\u003cp>大辉：值啊，你知道我等了多少年！第9部已经是在6、7年前了。这部电影不但有速度、还有很多美景！\u003c/p>\u003cp>兰兰：是吗，你这么一说，我也想去看了！\u003c/p>\u003cp>大辉：当然了，这个一个大IP，是个很牛的电影，就和变形金刚一样，都是非常棒的！\u003c/p>\u003cp>兰兰：变形金刚我也没看过啊\u003c/p>\u003cp>大辉：那就更应该看一看了，因为这是一个系列电影，非常非常酷。而且这个电影不光是赛车，还有很多人文的东西，还有美国的整个自然风光都表现的非常酷，绝对是美国大片！\u003c/p>\u003cp>兰兰：那现在还能买到零点的票吗？我跟你一起去看吧！\u003c/p>\u003cp>【观影中】：\u003c/p>\u003cp>兰兰：电影开始了，我们做好观影的准备吧。\u003c/p>\u003cp>大辉：嗯，大家都不要说话了，看电影的时候就享受这个场面就好了！\u003c/p>\u003cp>【观影后】：\u003c/p>\u003cp>兰兰：这个场景真的很真实，我都感觉我的心要跳出我的胸腔了，太惊险刺激了。\u003c/p>\u003cp>兰兰：今天来的人真多，黑压压的一片，都坐满了！\u003c/p>\u003cp>大辉：你从来没有看过零点场吗？我看过很多部电影都是零点场，那种兴奋绝对不一样，因为买到零点场的，都是狂热分子！你会真正体会到这个电影的感觉。\u003c/p>\u003cp>兰兰：我今天是疯了，年龄大了很少有熬夜，冲动了一把，但是确实很值\u003c/p>\u003cp>（反馈）谢谢兰兰和大辉的分享，我觉得我都已经热血沸腾了，我一定会带着我的家人们去看这场电影。\u003c/p>\u003cp> 通过预期来增强观影体验，在观影时全情投入，之后回味分享令人兴奋不已的场面和反应，这部富有极速运动感的电影就不仅止步于简单的视觉享受，它能带来更持久的心理体验和共鸣。这也是品味生活的真谛——由预期引发，在当下全然体验，之后津津乐道。简单的周末放松也成就生活中的美好记忆。\u003c/p>\u003cp>练习在生活各个方面预期美好、全情投入与回味,生活的每个瞬间都可以成为美好时刻,这需要养成一种心智习惯，但收获的快乐和满足感会让生命充盈不已。\u003c/p>\u003ch2>【A2】催化应用/15分钟\u003c/h2>\u003cp>请大家翻开资料的最后一页。\u003c/p>\u003cp>因为刚刚过去了五一小长假，短期内大家可能不会有旅游的计划，不过在日常生活中，我们还有很多可以应用这个方法的场景。\u003c/p>\u003cp>比如一次美食体验，从味蕾的期待开始，到用餐的每一口味道，再到回味美食带来满足感。\u003c/p>\u003cp>比如与好友相聚，预期叙旧的欢乐，活在当下的互动中，之后回顾一天的收获和感受。\u003c/p>\u003cp>比如读一本书，预期阅读的乐趣，透彻地进入故事世界，读后回顾感动和收获的片段。\u003c/p>\u003cp>比如聆听一段音乐，预期被美妙旋律打动，沉浸在音乐带来的情绪体验中，结束后回味其中的感动时刻。\u003c/p>\u003cp>比如一次运动锻炼，预期运动带来的活力和喜悦感觉，尽情运动，之后回味身体的畅快和成就感。\u003c/p>\u003cp>……\u003c/p>\u003cp>接下来的一个周里，你想在哪一件小事上尝试一下品味美好呢？先给大家1分钟时间思考一下，写下关键词。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>浩浩：美食\u003c/p>\u003cp>大辉：亲子游\u003c/p>\u003cp>兰兰：读一本书\u003c/p>\u003cp>代宁：写一篇文章\u003c/p>\u003cp>涛涛：老友聚会\u003c/p>\u003cp>洋洋：玩玩具和吃零食\u003c/p>\u003cp>可乐：看故宫\u003c/p>\u003cp>（一分钟后）接下来大家从这个关键词出发，按照品味美好的三个步骤，思考一下打算怎么做，可以在纸上写下关键词，然后在小组内分享交流一下，给大家10分钟时间。\u003c/p>\u003cp>小组讨论完，请一位小伙伴来做分享。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>大辉：\u003c/p>\u003cp>【预期美好】\u003c/p>\u003cp>我们作为拆书家，我想要带着孩子做一个既有学习，又有享受，很快乐的一个暑假。我们可以到一个有历史、文化的城市，这个城市有很多的历史、好玩的地方，也有很好的美食。让孩子们来做导游，我们负责后勤的住宿啊、吃饭啊什么的，让小朋友带着我们出去玩。等到很久之后，想想我家孩子从小就带我出去玩，这种感觉让孩子一下觉得成为主人的感觉，觉得我已经长大了。\u003c/p>\u003cp>【沉浸其中】\u003c/p>\u003cp>在这个过程中，我们会很享受这个过程，首先会感受到孩子长大了，他是一个独立的人，他会有自己的想法。小朋友也会感觉很快乐，这是他们自己的选择，这个城市里你感兴趣什么，比如你感兴趣吃，那你就带我们大人去吃吧，你要感兴趣玩，那就带我们去爽吧。\u003c/p>\u003cp>【回顾回味】\u003c/p>\u003cp>过程中我们会拍很多照片，留下许多美好的回忆，回来以后可以做成相册，大家一起回顾让自己印象最深刻的事情。还可以写了2000个游记，记录自己的感受。\u003c/p>\u003cp>（反馈）\u003c/p>\u003cp>谢谢大辉的分享，这真的是一个非常有意义的活动，我也期待今年的假期咱们就可以把它落地实现，非常美好的一件事。\u003c/p>\u003cp>练习在生活各个方面预期美好、全情投入与回味，生活的每个瞬间都可以成为美好时刻，这需要养成一种心智习惯，但收获的快乐和满足感会让生命充盈不已。\u003c/p>\u003ch1>\u003cstrong>结语/1分钟\u003c/strong>\u003c/h1>\u003cp>各位伙伴，今天我们学习了情绪管理的两个方法，一个是通过反驳消极思维来减少消极情绪，一个是通过品味美好来增加积极情绪。希望大家可以在以后的生活中去用起来，培养积极情绪，获得更多的快乐、感激和爱！\u003c/p>\u003cp>谢谢大家的聆听，希望可以让你有所收获。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1684620214000,"updated_at":1684980484000,"ria":true},{"id":10697,"topic":"正确道歉四步法","learn_goal":"","remark":"拆解书籍为《情绪的力量》","level":"TF2-3","duration":23,"status":30,"type":0,"chaishujia":{"username":"阿静","city":"合肥"},"club":{"name":"合肥霸都分舵","city":"合肥"},"prologue":"\u003cp>开场：\u003c/p>\u003cp>【自我介绍】\u003c/p>\u003cp>大家好，我是阿静，是一名一级拆书家，今天是我2-3的拆书分享。\u003c/p>\u003cp>技能点：【分组】（要求：在进入【A】之前进行分组。）\u003c/p>\u003cp>为了方便下面的学习和待会的小组讨论，我们分一下组。我左手边为一组，右手边为一组。\u003c/p>\u003cp>\u003cstrong>\u003cu>技能点：【图书介绍】\u003c/u>\u003c/strong>：在FAB介绍法中，能够清晰辨出聚焦于图书和学习主题的 F、A、B\u003c/p>\u003cp>F： 我们接下来要学习的拆页片段来自于2020年8月中信出版社的《情绪的力量》，书的作者是美国的利兹·福斯利恩和莫莉·韦斯特·达菲，两位作者在行为设计和咨询领域有非常丰富的经验，这本书中介绍了从健康、动力、决策、团队、沟通、文化和领导力七个方面介绍了职场情绪解决方案，帮助你清醒头脑，关照自己的情绪。\u003c/p>\u003cp>A：相比于其他沟通类书籍，这本书中通过157幅原创爆笑漫画，在轻松愉快的环境下，治愈你的坏情绪。这本书也是一本现代情绪应对指南，一经出版，就受到了很多人的欢迎。\u003c/p>\u003cp>B:\u003c/p>\u003cp>B1 ：如果你也经常感觉和朋友相处不好，和上司容易冲突，自己经常性地生气、发火，那么这本书就是一剂治愈情绪的良药。\u003c/p>\u003cp>B2：如果你做错了事情，不知道如何向别人表达歉意，那么今天我们接下来就会学习书中的一个片段来帮助大家解决这个问题。\u003c/p>\u003cp>技能点：学习目标包含学习者可被观察到\\被测量到的行为或动作，现场学习者设计清晰体验了该学习目标\u003c/p>\u003cp>今天我们的学习目标是通过现场学习，可以学会使用道歉四步法来向别人表达歉意，改善人际关系。\u003c/p>\u003cp>下面给大家2分钟时间阅读原文片段，阅读完后可以抬头示意我一下。\u003c/p>","ratings_count":1,"texts":[{"id":14568,"quote":"\u003cp>【技能点】【R】所选拆页，包括how的内容；且总内容未超过2页图书内页\u003c/p>\u003cp>\u003cstrong>R·阅读原书拆页【2分钟】\u003c/strong>\u003c/p>\u003cp>原文片段:选自《情绪的力量》一书 \u003c/p>\u003cp>当你向他人表示歉意时，请记住3个步骤。\u003c/p>\u003cp>1.承认自己的错误。记得压制自己解释的冲动——不然你会显得很有戒心，甚至会让人觉得你已经开始找借口开脱了。如果你想说明情况，首先要明确自己为行为担责的态度，例如，“我确实打断你说话了。前一天晚上睡得不好，不过这也不能作为我行为不得体的借口”。而且一定要具体！汤姆建议：“具体的描述能够让对方知道你理解他们谈话的来由。”最后，诚恳面对对方的感受。你可以说：“我之前不知道你觉得我发的邮件简单粗暴。谢谢你告诉我。”\u003c/p>\u003cp>2.说“对不起”。有太多的“道歉”缺少一句明确的致歉语。另外，“对不起”这个句子只应该有3个字。一旦加上“如果我粗鲁的行为让你感到不舒服”，这句“对不起”就立马显得非常虚伪了。不要在道歉中暗示对方过于敏感，要为自己的错误承担责任。\u003c/p>\u003cp>3.表明这类情况不会再次发生。告知对方你的行为将会有什么改变，避免同类错误的出现。\u003c/p>\u003cp>道歉举例：“我没有仔细校对就发给客户了，所以出现了几个拼写错误。对不起，不会再出现这样的错误了。下次我会慢点校对，然后再让别人核查一下。”\u003c/p>","explains":"\u003cp>好的，我看大家基本都看完了。\u003c/p>\u003cp>\u003cstrong>【What】\u003c/strong>\u003c/p>\u003cp>这个拆页片段告诉我们如何向他人表示歉意。\u003c/p>\u003cp>\u003cstrong>【Why】（一般做法）（不那么做的坏处）\u003c/strong>\u003c/p>\u003cp>通常大家做错了事情，会怎样做呢？是默不吱声想让事情过去，让对方忘记？还是虽然心里知道错了但嘴上说不出口？又或者是心里很着急，但却没有好的方法来处理，觉得很内疚？又或者嘴上说着抱歉，心里却不服气？如果我们做了错事，尤其是伤害到别人的时候，沉默会让彼此产生更多的误会。同时埋在心里也会让我们的内心很煎熬。敷衍式的道歉让别人感受不到你的真诚，长久下来，就会影响到我们的人际关系和生活。\u003c/p>\u003cp>\u003cstrong>【How】细化行动步骤或意译案例\u003c/strong>\u003c/p>\u003cp>那么，怎样来向对方表达自己的歉意呢，我将其根据原文细化为4个行动步骤：\u003c/p>\u003cp>1. 调心态：在意识到自己错了后，调整自己的心态。告诉自己：不要拼命给自己找借口，要接受自己做错了这件事。同时可以做深呼吸等调整自己的情绪。\u003c/p>\u003cp>2. 说行为：可以向对方说明你做了哪些事情，伤害到了对方哪些利益和感情。\u003c/p>\u003cp>3. 加歉语：在事件后面，加上“对不起”三个字，明确表达你的歉意。\u003c/p>\u003cp>4. 做保证：对对方做出保证，下次一定不会出现类似事情，也可以提出自己的补救措施或者下一次的解决方案。\u003c/p>\u003cp>\u003cstrong>【案例】\u003c/strong>\u003c/p>\u003cp>这让我想起来，前段时间，我有一个学生在微信上问我一个题目，但因为我看到消息的当下事情比较多，忘了回复。事后等想起来，已经快上课了。而事后也因为碍于面子也没有给孩子道歉。现在想想，孩子可能心里也不确定下次有问题了是否还敢来问老师。\u003c/p>\u003cp>如果当时，我用今天学到的道歉四步法，情况可能会好一点：\u003c/p>\u003cp>1. 调心态：在发现自己没有回复学生消息后，及时对自己说：这件事是我不对，我需要向学生道歉，深呼吸，保持好情绪。\u003c/p>\u003cp>2. 说行为：我会告诉学生：不好意思，刚刚老师在忙没有给你回复，让你久等了，估计你也着急了吧\u003c/p>\u003cp>3.加歉语：之后我会说：对不起\u003c/p>\u003cp>4. 做保证：下次老师有时间会及时回复你的消息，在忙也会给你说明一下，和你约定时间来回复你~\u003c/p>\u003cp> 相信这样，也会增加学生对我的信任感，巩固我们之间的关系~~\u003c/p>\u003cp>\u003cstrong>【where】\u003c/strong>\u003c/p>\u003cp>文中提到的道歉方式适用于对你来说重要的场合以及时间充裕的情况下。如果事情本身很小，比如你不小心碰了别人一下，这个时候只需要简单说一声谢谢。如果当下时间来不及，也可以事后进行说明。这个片段也更适用于生活中经常会发生的事件。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>预防1：有的小伙伴可能会觉得自己当下不好意思面对面向对方说明。那么也不要紧，你可以先自己写下来，通过电话或者邮件的形式来表达，对方也能感受到你的真诚。\u003c/p>\u003cp>预防2： 有的小伙伴可能会说了，有时候只靠嘴道歉让人觉得光说不做。其实嘴上道歉是向别人表明我们真诚的态度，你也可以做一些其他的事情搭配来道歉，比如登门拜访或者请客吃饭、送小礼物都可以。\u003c/p>","interaction":"\u003cp>\u003cstrong>A3激活经验-场景设计-角色扮演\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A3之场景设计提问】\u003c/strong>\u003c/p>\u003cp>刚才我们学习了道歉的四步法，接下来呢我们一起来做一个演练。\u003c/p>\u003cp>首先呢，要请大家认真听一下要演练的场景：\u003c/p>\u003cp>乐乐是一名小学四年级的学生，一天，乐乐的表妹来家里玩，看到了乐乐的奥特曼，非常喜欢，妈妈就在乐乐不知道的情况下把这个玩具送给了乐乐的表妹。等乐乐放学回家，发现自己的奥特曼没了。于是就询问妈妈，当得知自己心爱的玩具被送给了妹妹后，乐乐非常生气和伤心。\u003c/p>\u003cp>\u003cstrong>【小组讨论】\u003c/strong>\u003c/p>\u003cp>现在，我们两人一组，进行演练。一个人扮演乐乐，一个人扮妈妈。请妈妈用刚才的道歉4步骤--调心态-说行为-加歉语-做保证，向乐乐表达自己的歉意。大家按刚才的分组来讨论，编写你们的剧本。稍后我会邀请一组小伙伴，来进行现场分享。\u003c/p>\u003cp>\u003cstrong>【A3之角色扮演】现场演练\u003c/strong>\u003c/p>\u003cp>哪一组小伙伴愿意上台分享？好，那要不就素芬与慕色吧。\u003c/p>\u003cp>你们两个谁来饰演乐乐，谁来扮演乐乐妈妈？\u003c/p>\u003cp>回答：素芬来扮演乐乐，慕色扮演乐乐妈妈。\u003c/p>\u003cp>\u003cstrong>学习者现场分享：\u003c/strong>\u003c/p>\u003cp>（场景选择：乐乐放学回家，进门询问妈妈奥特曼玩具的事情）\u003c/p>\u003cp>乐乐：妈妈，今天我们班同学在玩奥特曼玩具，我的奥特曼玩具呢？\u003c/p>\u003cp>乐乐妈妈：噢，今天你表妹来家里，挺喜欢，我就送给她了。\u003c/p>\u003cp>乐乐：妈妈，你怎么可以不经过我的同意，把我的玩具随便送给人呢？那可是我最喜欢的奥特曼呀!\u003c/p>\u003cp>(乐乐大哭了起来)\u003c/p>\u003cp>乐乐妈妈意识到自己不应该把孩子的玩具随便送给别人，想着应该向乐乐道歉\u003c/p>\u003cp>乐乐妈妈小声对自己说道：今天确实是我不对，不应该把孩子的玩具随便送人，我应该向孩子道歉（第1步：调心态）\u003c/p>\u003cp>乐乐妈妈：乐乐，妈妈知道错了，今天不应该不经过你的同意把你的玩具送给妹妹（第2步说行为），对不起（第3步加歉语），下次我一定会征求你的同意后再送给别人。为了弥补妈妈的错误，妈妈待会带你去吃肯德基，好不好？（第4步做保证）\u003c/p>\u003cp>乐乐：好的，妈妈，我原谅你了\u003c/p>\u003cp>\u003cstrong>【总结】\u003c/strong>\u003c/p>\u003cp>感谢小伙伴的分享，非常的生动形象。让我们回顾一下刚才的演练，两位小伙伴也是运用了道歉四步法，当乐乐妈妈意识到自己做错了后，第1步先调整自己的心态，告诉自己虽然自己是妈妈，但是做错事情也需要向孩子道歉。第2步说行为，妈妈说不该在不经过乐乐的同意下就将玩具送给了表妹，第3步加歉语，妈妈对乐乐说了对不起，第4步，做保证，妈妈对乐乐承诺下次如果要送乐乐的东西给其他人一定会征求乐乐的同意，同时妈妈也为这次的行为提出了一个补偿方案，请乐乐吃肯德基。我们能看到乐乐妈妈很好地向孩子表达了自己的歉意，安抚了孩子的情绪，同时也给予了孩子尊重。\u003c/p>\u003cp>最后，我们回顾一下今天的拆书内容，我们学习了如何道歉的四步法，是调心态、说行为、加歉语、做保证，期待大家都能用在自己的生活中。\u003c/p>\u003cp>以上就是我本次的拆书，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1606487845000,"updated_at":1606743527000,"ria":true},{"id":9001,"topic":"制作属于自己的积极情绪档案","learn_goal":"分享在生活中增加积极情绪的方法","remark":"《积极情绪的力量》是积极心理学领域的著作，作者芭芭拉•弗雷德里克森多年致力于积极情绪的研究。在书中作者提出了积极情绪与消极情绪的最佳配比应该达到3:1（同时小于11:1），并给出了实现最佳情绪配比的具体方法。","level":"TF1-1","duration":15,"status":29,"type":0,"chaishujia":{"username":"卷毛小蓝","city":"上海市"},"club":{"name":"上海申活分舵","city":"上海市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp;1）自我介绍（30s左右）\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 大家好，我是卷毛小蓝，是一个新手拆书家。本职工作是人才测评，例如个性测评、智商测评等等，感兴趣的朋友我们可以多交流。个人爱好是听故事或者看故事，喜欢一切跌宕起伏的故事清洁，获取故事的手段除了看小说之外，就是听熟悉的人或者陌生人讲故事。来拆书帮参加活动也能听到很多有趣的故事，这也是拆书帮吸引我的地方之一。\r\n &nbsp;&nbsp;\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 2）拆书法和拆书帮介绍（2分30秒）\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;说到拆书和拆书帮，按字面意思就是把书拆了读，但拆书并不仅仅是一种阅读方法，更是一种学习方法。拆书学习法的核心在我看来就是拆为己用。怎么才能算是拆为己用呢？首先，学习的出发点是自己，根据自己的需要去读书，看书可以只看自己需要的部分，只看自己需要的书，而不需要强求自己把全书都读完。其次，用对方法，把学习的内容变成自己的。这里介绍一下拆书帮RIA学习法，也是今天几位拆书家会带着大家一起体验的方法。R（reading）就是读书，阅读原文。I（interpretation）要用自己的话来解释原文。为什么要做这么一个环节呢？目的就是检验自己是不是真的有掌握文中的内容，因为除了用自己的话去复述原文之外，还要思考原文在什么情况下是适用的，什么时候不适用，背后的原因是什么，有一些什么假设，如果不做有什么结果，这些都是大家可以在这个环节考虑的。最后是A （appropriation）环节，要联系自己。要分两步走。第一步找到自己过去经历中和原文相关的部分，成功或者失败的例子，越具体越好，思考成功或失败的地方。第二步按照原文说的方法制定一个具体的行动计划，是你真心想要去做的。因为只有落实到行动上才能算真正做到拆为己用了。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;说完拆书再说一下拆书帮，拆书帮是一个基于拆书学习法的公益组织或者说社群，由一群热爱学习、关注自我成长的青年人组成，在他们眼里，万物皆可拆。分舵是拆书帮组织各种活动的实体单元，大家在这里可以参与拆书活动，就像今天一样，也可以像我一样开始升级打怪，成为一个拆书家。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 以上就是我对自己和拆书帮的一个介绍。\u003c/p>","ratings_count":1,"texts":[{"id":12742,"quote":null,"explains":"\u003cp>R（2分钟）\u003cbr>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 今天我分享的拆页来自《积极情绪的力量》这本书（展示书籍），是积极心理学领域的一本比较经典的著作。作者是多年研究积极情绪的一位心理学家。我在豆瓣上看过这本书的评论，有的人打分很低，说这不就是鸡汤嘛。其实积极心理学和心灵鸡汤最主要的区别，心理学的结论是根据实证的科学研究来的，并不是给大家画饼，结论是可以重复验证的。下面请大家阅读一下原文拆页，读完就抬头示意我。（发拆页）\u003c/p>\u003cp>I（6分30秒）\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 在拆页中，作者给出了一个创造积极情绪的方法，为每一种积极情绪制作档案袋，当你被消极情绪拉入泥潭的时候，可以拿出这个档案袋来保护自己，重燃生活的热情，找回自己的积极情绪。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 根据进化论，远古时代我们的祖先生活的非常艰辛，经常要面对饥饿、猛兽、天灾，需要时刻警惕，傻白甜的个体容易被吃掉或者挂了。一来二去关注负面因素，抑郁、焦虑和恐惧等消极情绪随着基因就一直到了现在。虽然现在已经变得比较安全了，不会突然有老虎把你吃掉，但人们还是很容易关注负面的东西，容易忽视生活中的“小确幸”。而积极情绪与人际关系的和谐、身体健康、思维的开放性和创造力都非常相关。作者和同事研究发现，积极情绪和消极情绪在你生活中的比例能够高于3:1，就是3个积极情绪对1个消极情绪，是比较理想的状态。作者在研究中测试人们的积极率， 发现80%的人得分低于3:1，平均大概在2:1，抑郁的人群往往低于1:1，消极情绪的比例会超过积极情绪。为了让我们的生活更幸福一些，很有必要做些什么去调整。令人高兴的事情就是虽然基因决定了我们一半对消极情绪的关注，但还有一半的空间可以靠后天来塑造，可以自己创造积极情绪。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;创造积极情绪有很多种方法，那为什么要做一个积极档案呢？有些人说我觉得我现在过的还可以啊，很开心、很快乐，我真的需要一个积极档案吗？但天有不测风云，人生不如意事常八九，当我们遇到问题的时候，可能会被这种突如其来的问题打败，陷入消极情绪的泥塘，如果我们平时没有积累或留心的积极情绪的话，其实还挺难走出来的。如果有精心准备的积极情绪档案的话，可以在你被困住的当下，可以给到一个很好的力量平衡，让自己从消极情绪中走出来。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 当然它也不是万能的，当我们的朋友和家人已经有明确的抑郁症、焦虑症的时候，实际上更需要寻求专业人士的帮助，例如心理咨询，光靠看积极情绪档案是起不到效果的。刚刚我们提到积极情绪和消极情绪的比例要高于3:1，但关注积极情绪占比并不意味着要消灭消极情绪，消极情绪有的时候是挺必要的，大家可以回想一下过去的经历，当我们比较不顺的时候其实可能是让自己反思和改变的契机。研究发现积极情绪的占比并不是越高越好，积极率不要超过11:1，太高的积极情绪占比会让人脱离现实，光自嗨了，不能面对真实客观的现实。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;那么如何去制作一个积极情绪的档案袋呢？首先确定一个积极情绪的主题，例如让你感到喜悦，或者是让你感到自豪、感激。然后把与这个情绪主题相关的内容收集起来，可以是实实在在的物品，亲密的朋友家人相关的东西，一场精彩的演唱会，也可以电子的形式，电脑上的照片、日记、歌曲。可以放在真实的档案袋里，也可以贴在本子上，例如有些女生有收集东西的那种本子，或者建立一个电子文件夹。在完成这个过程的时候不要着急，可以给自己充足的时间，一定要体会自己再次遇到这些东西时内心的感受如何，回忆当时的场景和当时的感受。在整理过程中，不用在意是否正确、是否符合规则，因为每个人的情绪都是个性化的体验，你可以按照你喜欢的方式去建立档案袋。同时这个档案袋是动态的，你可以一直往里面添加新的素材。最后当遇到不如意的时候就可以把它拿出来，带给自己力量，例如觉得不自信的时候把自豪主题或者激励主题的档案袋拿出来。你可以按照不同的积极情绪主题建立各自对应的档案袋，书中提供了10种积极情绪档案袋建立的指导语。\u003c/p>","interaction":"\u003cp>A1（1分钟30秒）\u003cbr>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;分享我自己的一个故事。我虽然没有一个正式的积极档案袋，但平时喜欢用朋友圈记录生活的细节，一般只发自己喜欢的内容，难过的心情比较少发了，蓝天白云路边野花啊，小猫啊，吃吃喝喝等等，一度有朋友觉得我的日常就是吃喝玩乐，其实不是这样的。2017年的元旦小长假，我和闺蜜两个人去南京紫金山上一个民宿呆了3天，我们两个都有点不开心，因为工作和生活上的事情，我闺蜜比我更不开心一点。12月31日那天，我们两个吃晚饭开始互相倾诉，还抱头痛哭来着，然后又互相安慰。晚上闺蜜在优酷上刷剧，我在b站上刷日本J家的跨年和红白歌会，当天被美食、闺蜜和喜欢的idol围绕，度过了自己的生日和新年第一天，相当于集中了能让自己感到幸福的元素，积极档案的现场版，将来做积极档案都可以收集。同时我还翻看了16年一整年发的朋友圈，一篇一篇细细去看。我印象中看完之后觉得那一年做了很多挑战的事情，面对了很多未知的情况，虽然元旦那个时间点遇到了困难和不自信，但过去一年其实也是这么过来的，那个时候能做到以后也就能做到，变得对生活更有信心了一点。后来就养成了习惯，每年的元旦小长假都会回看过去一年的朋友圈，然后写一篇公众号来总结过去、畅想未来。我觉得这种做法有些接近积极档案袋，但使用的频率有些低，如果能在情绪低潮的时候，及时可以找到自我激励的东西，效果可能会更好。\u003c/p>\u003cp>A2（1分钟）\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 最后说说行动计划，最近我有点暴躁，可能是因为工作任务的不确定性和咳嗽一直好不了，比较容易焦虑和难过，所以打算按照书中的说法做一个“宁静”主题的档案袋，找到让我感觉内心宁静很peace的东西，暴躁的时候就可以拿出来安抚自己一下。正好这个周末有时间去做，下次来拆书帮的时候给大家分享一下我的感受。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 书里还有很多降低消极情绪、提升积极情绪的方法，建议大家读一读这本书，并找几个合适自己的方法去实践，相信会有奇妙的事情发生。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1570272880000,"updated_at":1570284777000},{"id":6103,"topic":"拆除消极情绪地雷，减少消极情绪；品味美好，增加积极情绪。","learn_goal":"遇到无法避免引发消极情绪时，能够使用三个办法来减少情绪产生","remark":"这是一本改变人类命运的书，一本教我们追寻幸福的书。通过书中所列出的10多种方法，我们可以提升自己由衷的积极情绪，降低有害的消极情绪，最终实现欣欣向荣。该书被积极心理学之父塞利格曼、心流之父希斯赞特米哈伊、情商之父戈尔曼倾情推荐，被哈佛大学、剑桥大学、全球华人积极心理学协会高度赞誉。","level":"TF2-4","duration":55,"status":30,"type":0,"chaishujia":{"username":"jiafeimao","city":"太原"},"club":{"name":"太原黄河分舵","city":"太原"},"prologue":"\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp; 【学习目标】\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者在遇到无法避免的引发消极情绪的情况时，能够使用三个办法来减少无端的消极情绪的产生；学习者在遇到好事情时，能够采用四个步骤从多个方面去品味美好，增加积极情绪。\u003c/p>\u003cp>\u003cstrong>【自我介绍\u003c/strong>】\u003c/p>\u003cp>大家好，欢迎大家来到今天的拆书现场，我叫肖蓉，是一名事业单位的科研人员。上班时间，我用小白鼠做各种实验，验证自然规律。下班时间，我把我自己当作小白鼠做实验，验证各种工作高效方法、育儿方法、沟通技巧。所以我的一个标签就是“永远的践行者”。我的另一个标签是“一级拆书家”。\u003c/p>\u003cp>\u003cstrong>【分组\u003c/strong>】\u003c/p>\u003cp>为了接下来的讨论更方便和高效，首先我们进行分组。我左手边的小伙伴一组，右手边的小伙伴一组。\u003c/p>\u003cp>【\u003cstrong>图书介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>F\u003c/strong>\u003cstrong>特征（核心是书，用于满足好奇心）\u003c/strong>\u003c/p>\u003cp>今天跟大家一起分享的是《积极情绪的力量》。该书的作者是芭芭拉·弗雷德里森。她是北卡罗来纳大学杰出教授，很杰出的积极情绪研究者。 2000年，因她在积极心理学领域的杰出贡献，美国心理协会授予她坦普尔顿奖。坦普尔顿奖的影响力及奖金额堪比诺贝尔奖。\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp; A\u003c/strong>\u003cstrong>优势\u003c/strong>（重点是比较）\u003c/p>\u003cp>与其它同类书相比，该书是作者在十几年间通过一系列针交互验证和实证研究的结果，有着坚实的理论基础。而且作者细心地将清冷的科研成果揉入温暖的生活实例当中，将自己人生的感悟、事业与积极情绪螺旋上升的动态模型巧妙结合、娓娓道来，让读者在层层的共鸣、感慨和回味中品尝到积极情绪的馈赠。\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp; B\u003c/strong>\u003cstrong>利益\u003c/strong>（强调学习者的利益）\u003c/p>\u003cp>\u003cstrong>B1\u003c/strong>\u003cstrong>：\u003c/strong>我们都知道积极情绪能让生活变好，许多书许多人都在倡导说我们要积极乐观，可是生活中还是会难以避免的出现低沉，担忧，恐慌等消极情绪，它们的确是与我同在的。那么，怎样才能在积极情绪和消极情绪之间寻找一个平衡点，让积极情绪带给我们更大的益处，让消极情绪带给我们尽量少的伤害？这本《积极情绪的力量》中一定有你想要的答案。\u003c/p>\u003cp>\u003cstrong>B2\u003c/strong>\u003cstrong>：\u003c/strong>今天跟大家分享的第一个拆页是关于如何减少消极情绪方面的，第二个拆页是关于如何增加积极情绪方面的。学习者能够通过这两个拆页的学习掌握拆除消极情绪地雷的三个方法和品味美好，从好事情中增加积极情绪的四个步骤。\u003c/p>","ratings_count":1,"texts":[{"id":9357,"quote":"\u003cp>拆除你的消极情绪地雷\u003c/p>\u003cp>当然,你无法避免所有引发消极情绪的情况,就好像你每天的上下班和洗衣服、看牙医不可避免一样。如果你不能避免引发不必要的消极情绪的情况,你至少有三个办法来制止它:你可以改变情境中的消极要素;你可以植入带来积极情绪的要素;或者你也可以改变它的意义。\u003c/p>\u003cp>你可以改变消极要素。假设你认识到,上下班对于你的积极率是一个特别的拖累。虽然你完全可以选择远程办公,或是搬到市中心的一个离你的办公室大门只有几步之遥的公寓里,但是假如在未来的至少一年左右,长途驾车是不可避免的,那要如何改变你的情况呢?例如,你想要更多地了解什么?物理?历史?诗歌?小说?无论是什么,你都能发掘无尽的潜力,把驾驶转变成一段令人愉快的学习体验。或者,你可以找一个人来与你分享你的旅行和学习体验。或者,你可以用坐火车或公共汽车来取代自己驾驶,并且用老式的做法—捧一本书蜷缩着,或用新式的做法,这完全取决于你。\u003c/p>\u003cp>你可以植入积极要素。假设你发现,你在每个工作日的早餐和午餐时间里充满了焦虑,你总是吃得很匆忙,并且心里还在思考如何安排今天的事务,这里就是你要对注意力进行分配的地方了,关注吃饭的那个时刻,放下你的关于“下面做什么”的想法，以“现在是什么”取代。如果我们全神贯注的话,吃饭本身就会带来愉悦和感激。将用餐的时间花在体验进食的感觉上,这样你不仅化解了不必要的消极情绪,而且还释放了隐藏着的积极情绪来源。注意你选择的食物的称心味道和口感;想一想你的食物来自哪里;想想参与到其中的农民、杂货店和厨师,他们的馈赠滋养着你。慢慢的,通过带着觉知力进食,你甚至可以减轻体重,因为你对于身体的微妙信号变得更敏感了。最重要的是,不要同时进行多种任务。你可以在用餐的之前或之后拨出时间来整理你的事务清单——在纸上或掌上设备中将它具体化,这样它就不会在你吃饭的时候侵入你的思维空间了。\u003c/p>\u003cp>你也可以改变触发过度消极情绪的事件的意义。我可以把“写一页半扔两页”理解成我是一个失败者,但是我也可以将它理解为我是一个作家。你可以把看牙医看做是一次痛苦的体验或者在不过度夸大的情况下,将它看做是一次对于不适的挑战，再或者,你可以选择将它作为一种必要的保护自身健康的手段来接受。\u003c/p>\u003cp>像这样的重新诠释,拔去了消极情绪的毒牙。一旦你对生活中反复出现的无端消极情绪的来源感到适应,你就会知道什么时候你最需要建立新的积极情绪。实验一下,将这些新的意义铺到你的新河床上。观察它让你感觉怎样,它如何让你平静并推动你前进。\u003c/p>","explains":"\u003cp>\u003cstrong>【What】\u003c/strong>有的消极情绪——比如对可能会伤害你的事物感到害怕——这种害怕会让你远离伤害，利于保护自己。比如，要上台演讲的时候会紧张，这种紧张会让你保持一种精神高度集中的状态，反而能让你上台演讲得更好。像这一类型的消极情绪对你的生活是有益的。这叫“必要的消极情绪”，我们接纳它就好。在本拆页中我们讨论的是要减少“无端的消极情绪”。什么叫“无端的消极情绪”呢？举例：比如你下班回家推开门，发现家里的熊孩子在沙发上又跳又叫。你工作了一天本来已经昏昏噩噩的大脑，现在被熊孩子的尖叫声和那满地的杂物搅得跟一团浆糊一样。这个时候你产生的那些不愉快的感觉，就叫“无端的消极情绪”，因为它没有任何用处，无论是对问题的解决还是对你的健康，都不会有任何好处。而且你发现在你的生活中这种情况会反复出现。每次遇到工作忙孩子又调皮的时候，你就心情极度不好。它就像一颗地雷埋在你身边，时不时的炸你一次。\u003c/p>\u003cp>\u003cstrong>【Why】\u003c/strong>我们大部分人都有这样的地雷，很烦人，对吧？\u003c/p>\u003cp>\u003cstrong>【不那么做的坏处】\u003c/strong>大部分人在面对这样的情况时要么是不知道自己正处于无端的消极情绪控制当中，要么即使知道也无力回天，只能自己一边心情很不好，一边还苦哈哈的继续完成后面的事情，还会把这种消极情绪发泄到另外的人身上——就比如刚刚的例子，你一边心里头极度郁闷，一边收拾孩子们扔了一地的玩具。收拾完之后看见老公扔在床上的外套，于是心情不好的你对着老公一通吼叫，埋怨他不帮忙收拾家还要乱扔衣服，一场新的战争即将爆发。\u003c/p>\u003cp>\u003cstrong>【How】\u003c/strong>较好的应对这种反复出现的无端的消极情绪的办法有如下三个：\u003c/p>\u003cp>第一，换——改变消极要素。找一找最让你不舒服的是哪一点，用别的替代品替代它。上班路途太远，坐公交很不爽，那就换成打车。\u003c/p>\u003cp>第二，加——加入积极要素。没有替代品替代，那就加一点你非常喜欢的东西进去，用喜欢的积极的东西化解、稀释不必要的消极情绪。就像刚刚的例子——你发现每次自己上班太累再遇到熊孩子淘气的时候就会产生消极情绪，那么下次当自己觉得今天忙了一天已经状态不好的时候就不要下班直接回家面对熊孩子，而是去做瑜伽、游泳等能让你自己先放松的事情，然后心情美美的回家。这样你就不会那么容易点炸了。\u003c/p>\u003cp>第三，重定义。同一件事情，你给它赋予的意义不一样，它带给人的心情就不一样。许多人手腕上带玉，某一天玉由于某种原因碎了，许多人会讲，这是玉帮自己挡了一次大灾难。玉通灵性，知道主人有难，牺牲了自己保全了主人。所以几万元的玉碎了带来的损失感瞬间降低，反而是一种躲过一场大灾难后的幸运感。这就是典型的将消极事件赋予积极意义的案例。\u003c/p>\u003cp>\u003cstrong>【更贴合实际的例子】\u003c/strong>给大家举一个我亲身经历的例子。在上小学五年级的时候，我转到一所新学校。学校到家中间有一段必经之路是长长的隧道。隧道里的灯很昏暗，而且由于地势低，隧道里经常积满了脏水。由于一些原因，父母不接送我。我特别害怕走那段隧道。我习惯骑自行车上下学，为了尽快通过隧道，我就把自行车骑得飞快。但是骑得快了自行车就会把脏水带起来溅我一裤腿儿。可以说，那段隧道是我上下学的噩梦。\u003c/p>\u003cp>路就这一条，父母也确实不能接送，看起来问题似乎永远没有办法解决。所以刚转学的那几周我很焦虑，充满了消极情绪。但好在这种焦虑情绪没有把我压垮，在焦虑了两个星期之后，我尝试主动去改变它，当时我是迫于形势，在学习今天这个拆页时，我发现我当年的那几个办法正好符合拆页中所说的三个办法。\u003c/p>\u003cp>首先我知道我是害怕一个人过隧道，那么最简单的办法就是再找一个伴儿。所以我主动打听本班和别的班级里谁跟我走的路线差不多。我主动去接近他们，并跟他们保持很好的关系，约他们一起上下学。我一共找到了5个这样的同学，能保证每天总有人能跟我一起走。我还发现，天黑会加剧我的恐惧。所以我坚决不会允许自己有拖拉课堂作业的情况。\u003cstrong>（改变消极要素）\u003c/strong>\u003c/p>\u003cp>另外我还发现那些脏水也容易让我不高兴。我就跟随行的朋友打赌，谁今天自行车骑下来一点都没有溅起脏水，谁就是赢家，输的要给赢的买雪糕。我们还常练习像男孩子一样骑车时把两条腿翘起来，让脏水溅不到裤子上。这样在很多时候，我都是和同伴们欢笑着一路通过了那条又脏又让人害怕的隧道。\u003cstrong>（加入积极要素）\u003c/strong>\u003c/p>\u003cp>后来在一次小学同学聚会上，一个当时的同行伙伴跟我说：你在我心目中的印象好完美，你那么主动，热情，讲义气，大方，经常给我们买雪糕，学习又好，还好酷，骑自行车花样那么多。\u003cstrong>（你看，这就是那条又黑又脏的隧道的意义）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>\u003c/p>\u003cp>本拆页所说的三个方法只适用于减少生活中反复出现的由无法避免的事件引发的无端的消极情绪，对于那些只可能出现一次的，完全可以避免的事情，不用这么费事，直接避开它就好。对于有些家庭中反复出现的大的伤害性事件，比如家暴，这个属于必要的消极情绪，不是本拆页讨论的无端的消极情绪，也不适用这3个方法。另外，当消极情绪正在发生时，你往往想不到使用这3个方法，我们应该在心情平静的时候仔细审视自己的日常惯例，来定位自己的消极情绪地雷，提前按这3个方法来想好对策。只有这样当事情发生时你才可能采取适当的方法来成功阻止无端的消极情绪。\u003c/p>\u003cp>\u003cstrong>【预防可能的异议】\u003c/strong>\u003c/p>\u003cp>有的小伙伴可能会讲，我即使知道我正处于无端的消极情绪控制当中，也知道了这三个方法，可我还是找不到具体有什么要素能换、能加，也找不到什么别的意义。那我怎么办？\u003c/p>\u003cp>如果你遇到了这样的情况，说明你真的遇到一个大的拦路虎。我们不要指望每次都能完全消灭消极情绪，而是给大家提供这样一种思路去积极改善。也许一次解决不了，但多多尝试，总能在某一时刻找到适合自己的好方法。\u003c/p>\u003cp>其实在这本书中，作者一直在强调一个概念——积极率（即积极情绪与消极情绪的比值），作者在书中特别地提到“你不需要苛求自己每时每刻都处于积极情绪当中，你只要尽力在几天甚至几星期的一段时间里将积极率提高到一定比值就可以了。”有关积极率的拆页以后有机会我会再跟大家一起分享。\u003c/p>","interaction":"\u003cp>【A1】在刚刚我们学习了在碰到无法避免的产生消极情绪的事件时，采用三个办法来避免不必要的消极情绪。现在我想请大家想一想，在你过去的生活中，有没有遇到反复发生的无法避免的消极事件呢？比如你爸每年都定期带你回老家看望奶奶，你其实非常喜欢回去跟奶奶聊天，但是一想起老家农村那种糟糕的厕所环境，你就提不起精神来了。再比如你有一份工作，是你喜欢的行业，工资很高同事也不错，但每年一到夏天你就开始焦虑，因为你的办公室在顶楼，而且没有空调。再或者，你的生活中总是会遇到“计划赶不上变化”的事情，而计划一旦改变，你就开始焦虑，开始抓狂。\u003c/p>\u003cp>请大家想一想自己曾经遇到的类似这样的“经常发生的无法避免的产生消极情绪的事件”，先在小组内分享一下，两分钟之后我会请小伙伴们给我们大家分享一下。\u003c/p>\u003cp>\u003cstrong>【A1+】\u003c/strong>如果时间能够倒流,大家能够怎样用刚刚学到的三个方法来重新应对你刚才想到的那件无法避免的消极事件，让你不再产生无端的消极情绪呢？\u003c/p>\u003cp>请大家还是在小组内先讨论，2分钟后我们会请几位小伙伴分享一下。\u003c/p>\u003cp>【案例】小艳：我遇到过这样的事。我母亲有一段时间跟我住在一起，她习惯早上起来拖地，拖完之后不等地干就走来走去，满地都是脚印。她是长头发，一梳头要掉好多。每天早上我一起来就看见卫生间脏脏的地板和一地的头发，我又是比较爱干净的人，所以心情就很不好。我告诉过她，可她还是这样。那段时间，我经常是早上一起来就开始心里头不高兴，还不能发作，毕竟那是母亲，而且人家是因为过来帮我照看孩子才跟我住在一起的。所以我只好自己把卫生间重新打扫一遍。这就是无端的消极情绪吧！\u003c/p>\u003cp>如果时间能够倒流，我采用今天的三个方法来应对这种情况的话，第一个“换”我换不了，第二个“加”我也加不了什么积极的东西，我采用第三个方法“重定义”吧，我就把这当作每天早上的减肥运动吧。正好我一直坚持不了减肥，每天早上那个糟糕的卫生间让我马上拿起拖把进行运动，让我的减肥运动计划执行力满满。\u003c/p>\u003cp>【\u003cstrong>我的回应与反馈\u003c/strong>】感谢小艳给我们分享的这个案例。她是从“重定义”方面去重新看待这件引发消极情绪的消极事件的。有的时候，我们并不能在三个方面都能找到对应的方法，但只要在其中一方面找到一个方法，解决了你的问题，拔除了你的消极情绪的地雷，就可以了。\u003c/p>\u003cp>【\u003cstrong>强有力的结语\u003c/strong>】在这里我们就记住一句顺口溜：一换二加三重定义。然后，我们看下一个拆页。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":9358,"quote":"\u003cp>品味美好\u003c/p>\u003cp>一线希望式的积极情绪源自从坏事情中找到好的方面,源自将消极的事物转变为积极的事物。提高积极情绪的另一种策略是从好事情中寻找好的方面,将积极的事物变得更加积极。你可以把这个称做锦上添花的积极情绪。\u003c/p>\u003cp>当有什么好事情将要发生在你的身上时,你会对自己说什么?当你被好运气包围时,你在想什么?或者当某些美好的事物从你后视镜的视野里退去时,你脑海中闪过的是什么?人们的反应各不相同。有些人让怀疑和猜忌带路,“这不会真的发生在我身上。”“这是不可能发生的!”或者“我知道这不会持续太久。”其他人会以这样或那样的方式,不对它多加考虑。美好仿佛突然接近了他们,接着又同样迅速地消失了。然而,有些人找到了品味美好的方法。\u003c/p>\u003cp>无论是在他们的未来、现在或是过去,他们以下面的这种方式来思考它,从而让它延伸、给它打气。在一些好事情发生以前,这些人可能会告诉自己,当…的时候就太美妙了。当这种事情发生的时候,他们可能会想,我真想完全陶醉在其中。然后,在这个事件过后,他们可能会在自己的想象中重演它,重温它带给他们的一切美好感觉。像这样品味的人们,能从生活中汲取更多的积极情绪。\u003c/p>\u003cp>人们是否会自然而然地品味美好,往往是一个关于自尊心的间题,关于他们是否觉得自己“应当得到”好事情在自己身上发生的运气。尽管如此,品味是一种你可以开发的心智习惯。在第5章介绍的我的实验研究,证实了品味的能力是你可以建构的一种资源。除了简单地接受美好,你还可以学会去品尝它、深深地欣赏它的每个方面。如果品味对你来说还很新奇,学习去做好它,随着你在愉快事件的前中后期提取出更多由衷的美好,这可以三重地加倍你的积极情绪。品味只是意味着以这样一种方式来考虑好事情,也就是你有意识地创造、强化并延长你对它们的由衷的享受。\u003c/p>\u003cp>品味需要你放慢脚步并有意识地去关注,这就好像花时间去欣赏准备一顿美餐所包含的各个好的方面,从感受新鲜蔬菜和调料的香气到沉醉于调配作料所带来的成就感。然后,当你完全沉浸在与朋友或家人一起分享你的杰作时,你能品味更多。\u003c/p>\u003cp>但是请记住,品味不是分析。提高积极情绪要求轻微的心理碰触,把经验作为一个整体来接受,欣赏它带给你的感觉。不要解剖它或是以其他方式把它扯开。回想一下那些证明了过度分析会打击积极情绪的实验。\u003c/p>\u003cp>品味不必是一种私人的活动。科学家已经证明,一个最简单的、加倍你从好运中获得积极情绪的方法,是养成与配偶、亲人或者亲密的朋友分享你的好消息的习惯。让他们参与到其中来,与你一起庆祝。你可能要怀疑,这个人会做出何种反应还不确定,他会给你泼冷水吗?或者表现出明显的沉默吗?或是做出评价:“他们对每个人都有奖励,你不知道吗?”或者,他们是否会真心为你的成功干杯,并鼓励你充分地享用和庆祝你的好运?如果他们积极地支持你,你从那个单纯的好消息中收获的积极情绪就会显著地增长,而且——作为额外奖励——你的人际关系会盛放。你们变得更加亲密,并且更加愉快地交织在一起。这给了你更多理由去品味,品味可以带来更多的积极情绪,你就进入了良性循环的领域。所有这一切都只是来自于对你的好消息的分享。\u003c/p>","explains":"\u003cp>拔除生活中消极情绪的地雷是一个伟大的开端，那是你在努力打好生活发给你的一手烂牌。但是假如生活发给你的是一手好牌呢？你要怎么样打好这一手好牌？我们不光要有减少消极情绪的能力，还要有提高积极情绪的能力，也就是说我们不但能从坏的事情中看到一线生机，还能从好的事情当中寻找好的方面，将积极的事物变得更加积极。\u003c/p>\u003cp>提高积极情绪的策略有好多种，其中一种就是我们今天的拆页二————品味美好。\u003c/p>\u003cp>\u003cstrong>【What】\u003c/strong>就算生活再艰难，也一定还是会有什么好事情突然发生在你的身上的。美好的事情能够带给人积极情绪。给大家列举一下常见的十种积极情绪：喜悦、感激、宁静、兴趣、希望、自豪、逗趣、激励、敬佩和爱。\u003cstrong>【Why】\u003c/strong>是不是每个人在遇到好事情时都会感到同样多的积极情绪呢？不是。想一想当有好事要发生在你身上的时候，你会对自己说什么？是说：哎呀，我踩上狗屎运了！还是说：哎呀，天上掉馅饼了！还是说：哇喔，我人品小爆发咯！说什么的都会有。你会发现有的人是肯定的，认为在自己发身上发生好事情，那是自然而然的事情，那是很正常的。有人却是带着怀疑和猜忌的：这样的好事真的会发生在我身上吗？甚至当好运包围他的时候，他还在怀疑“这是真的吗？这真的是给我的吗？”对于这些人来讲，就算生活给了他一手好牌，他也不能完全享受这手好牌。整日活在既怀疑这样的好牌是否真的属于自己，又害怕这手好牌随时会失去的焦虑和不自信中。\u003c/p>\u003cp>我们当然不希望这样，既然我们都能从坏事情中找到好的方面，那么从好事情中，我们理所应当找到加倍的好的方面，让好的事情释放更多的积极能量。这就需要提高我们品味美好的能力。\u003c/p>\u003cp>\u003cstrong>【How】\u003c/strong>怎样提高呢？拆页中有提到，但不够细化，\u003cstrong>我细化后的步骤如下\u003c/strong>：\u003c/p>\u003cp>\u003cstrong>第一，事前想象美好，让肯定和希望带路。\u003c/strong>有好事情要来，那我们就安然接受，热切的期盼它，想象这件事情将会怎样发生。不要怀疑”哪有这样的好事情”，也不要猜忌“应该不是给我的吧”。要记住，怀疑和猜忌可不是积极情绪的词汇哦。\u003c/p>\u003cp>\u003cstrong>第二，事中享受美好，深深的欣赏与强化。\u003c/strong>怎么叫深深的享受了，很简单，忘掉所有跟这件事不相关的其他任何事情，陶醉在当下。如果你是在进餐，那么就欣赏温馨的环境，精致的餐具，食物的香气。如果你足够享受，你会发现，每一粒大米都是那么晶莹剔透，每一片肉的纹路，都那么具有艺术感。\u003c/p>\u003cp>\u003cstrong>第三，事后重温美好，有意识延长享受。\u003c/strong>当事情结束之后，你可以在想象中重温它，这种美好的感觉会第三次带给你积极的力量。\u003c/p>\u003cp>\u003cstrong>第四，最后分享美好，让美好加倍。\u003c/strong>把你的好运分享给身边的人，用你的积极情绪去感染他们，从他们身上反馈回来的积极情绪会进一步加倍你的积极情绪，这就促进了积极情绪的良性循环。\u003c/p>\u003cp>\u003cstrong>【不这么做的坏处】\u003c/strong>大部分人只能做到简单的接受美好，在遇到重大的美好的事情时，才会做到去享受。而生活中许多细小的美好事情，都被他们忽略了，以至于他们常常认为自己的生活中没有什么好事情。殊不知，那不是因为没有美好，而是因为你不会“享受美好”。比如有人送给你一张免费的音乐会门票，你先是想到时候还不一定去呢，先搁在这儿吧。到了场馆里坐下后又想免费的票就是不好，这个位置都看不清演员的脸。结束后感叹乱哄哄的还不如在家看电视呢。但如果你按照今天拆页所说的4步法来对待这个事情的话，你先是想：哇，我终于可以近距离的看看周杰伦啦，而且还是免费的票，好激动呀。到了场馆坐下后你发现灯火辉煌，到处都是满脸激情的年轻人，自己仿佛也年轻了十岁，虽然看不清周杰伦的脸，但你知道他就在离你200米的地方，活力四射的表演。结束后你还处于兴奋当中，感叹年轻真好，以后还要经常来参加这样的活动，让人激情满满。回家后你告诉家人，下次要带上他们一起出来Happy，他们一定也很开心。大家看，这就是针对同一件事，会不会“享受美好”带来的天壤之别。\u003c/p>\u003cp>\u003cstrong>【预防可能的异议】\u003c/strong>有的小伙伴可能会说，要是我事前先想得太美好，结果事情由于意外情况没有发生，或者不是按我想象中的来，那我岂不是要失望？那还不如不要提前想，省得失望。\u003c/p>\u003cp>常言道：计划赶不上变化。可见事情不按计划的来是一种常态。计划好的事情会不会改变与我们提前想象它的美好是两码事。就算我们不事前去期待，它要变也还是要变的。就是因为我们一直在想“还不一定是咋回事呢，想那干嘛”，导致我们从不期待美好。学习了今天这个拆页，我们就是要改变以往的这种思维，热切的期待美好，不是还有一句俗语叫“心想事成”吗！倘若事情没有按预期的发生，那就接纳这个不发生。至少我们已经享受了一次美好了。\u003c/p>\u003cp>\u003cstrong>【适用边界\u003c/strong>】当然，我们在这里并不是让大家去做白日梦。如果是“白日梦”的话，大家永远只能在“事前”这一步停滞不前。我们这里讨论的是针对一件具体的事，根据事情的发展脉络从不同角度来享受美好。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3】\u003c/strong>刚刚我们学习了从“事前事中事后最后”四个方面来品味美好，从好事情中加倍的获得积极情绪，让积极的事物变得更加积极。那么现在我们来趁热打铁，现场演练一下这个新学到的技能吧！\u003c/p>\u003cp>假如有一天，交通银行的客服给你打电话，说你被挑选为幸运客户，邀请你参加周末在东山别墅区举办的交通银行客户答谢烧烤晚宴，完全免费，还有接送车。你通过各种途径核实了这条消息。是真的，确实这件好事情要发生在你头上。\u003c/p>\u003cp>请根据刚刚在拆页中学到的“事前，事中，事后，最后”四个步骤，在脑海中预演一下你如何在这段时间内尽情的享受这个美好，让它带给你多重的积极情绪。请先在小组内分享一下你是怎样享受的？你在各阶段体验到了哪些美好？5分钟后我们会邀请小伙伴给我们大家分享。\u003c/p>\u003cp>【案例1】小王：确实是个好事情啊！首先事前我会去网上查别墅区的位置，会征求主办方能否带上家人，我想把这份幸运和家人分享。去了那儿之后，我可能会感受到人家组织得挺好，会享受自己动手烤肉的愉快。结束之后在回家的路上，我会跟家人回想今晚的愉快的晚宴现场，会聊起几个特别的片段。最后回到家里，我可能会跟父母或亲朋打电话，告诉他们我度过的这个幸运又愉快的夜晚。\u003c/p>\u003cp>【\u003cstrong>回应与反馈】\u003c/strong>感谢小王的分享。从小王的讲述当中，我们跟着体验了整个烧烤晚宴带来的美好。我们能够明显感受到的积极情绪有喜悦、兴趣、希望、爱和感激。而且，小王已经完全Get我们所说的品味美好的四个步骤，咱们给她鼓掌！\u003c/p>\u003cp>【案例2】陈老师：我可能会在事前想象人们都穿着晚礼服，端着高脚杯，见不同的人。我将会认识许多不同的人，结交不同的朋友。坐到烧烤现场之后我会好好享受那里的食物和氛围。回来之后我会写文章分享整个过程，还会附上一些图片，这既是我自己重温这份美好，还能让我的朋友跟我分享这份美好。写完之后过段时间我自己会回看文章，会再次重温当时的美好。\u003c/p>\u003cp>【\u003cstrong>回应与反馈】\u003c/strong>好的，陈老师也已经完全Get我们所说的品味美好的四个步骤，从这件美好的事情当中体验到了多重的积极情绪。真的非常棒！\u003c/p>\u003cp>\u003cstrong>【A2】\u003c/strong>那么刚才是我给大家设定的一个想象的场景，接下来请大家自己设想一下，在接下来的一段时间内，你的生活中可能会出现什么样的好事呢？请大胆的畅想一下。也许是老板有一天告诉你，要给你加薪升职。也许是你的孩子由于表现特别棒被选为幼儿代表参加省电视台举办的少儿节目。也许是你获得一个超级优惠的出国游机会，正好国庆节你们一家到国外旅游一趟。也许是男朋友最近要去国外出差，他说要给你带一大堆礼物回来。\u003c/p>\u003cp>请想象一下，在接下来的一段时间最有可能有什么样的好事情要落到你头上呢？当好事情要发生时，你打算如何用今天所学的“”事前事中事后最后”四个步骤去品味这样的美好，让美好事情中的积极情绪成倍的放大呢？请写在便签上并在小组内分享一下。\u003c/p>\u003cp>【案例1】小田：我正好有这样一个好事情要发生。国庆的时候我准备带我妈妈和婆婆两个老人外出旅游。这个事情我现在就能提前想象，老人们穿着旗袍，拿着丝巾，摆了各种poss照上一堆照片，应该会很High。等到真的带她们出去的时候，我应该是充当摄影师的那个角色最多。从镜头里看见她们高兴的样子，我肯定也会很高兴的。事后她们旅游回来后，肯定会跟身边的人讲，我姑娘/媳妇带我去哪哪旅游啦，那儿风景很漂亮，饭多么好吃，玩得多么开心，把照片给别人看。这些消息可能也会反馈到我的耳朵边，别人可能会夸奖我是个好媳妇/好女儿，我当然听到这样的话也会很高兴的。最后，我也会把我带老人出去旅游的经验教训分享给身边有需要的人。\u003c/p>\u003cp>【\u003cstrong>回应与反馈】\u003c/strong>小田同学讲得真好，不仅完全掌握了品味美好的四个步骤，同时让我们又一次从她的这份美好中感受到了爱、感激、喜悦、自豪等积极情绪。我提议咱们给小田同学鼓掌！\u003c/p>\u003cp>好的，由于时间关系，我们就不再请小伙伴分享了。\u003c/p>\u003cp>【\u003cstrong>强有力的结语】\u003c/strong>总之，大家在以后遇到坏的事情时要记住那句顺口溜：一换二加三重定义。遇到好事情时，要记住从“事前事中事后最后”四个方面去有意识的创造、强化并延长对美好的由衷享受。\u003c/p>\u003cp>好，感谢大家参加今天的拆书活动，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1537345630000,"updated_at":1537346267000,"ria":true},{"id":5073,"topic":"积极情绪的力量","learn_goal":"能通过对比积极、消极和快乐情绪来描述自己所处的情绪状态","remark":"在面对消极情绪时候，用正确的方法甄别并加以利用，改变自己看待消极情绪的方式，用正确的态度面对未来","level":"TF3-3","duration":30,"status":30,"type":0,"chaishujia":{"username":"龚陟","city":"南昌"},"club":{"name":"南昌滕王阁分舵","city":"南昌"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家好，欢迎来到拆书帮TF3-3的活动现场。我是今天的拆书家--龚陟。现现在来为大家做一个分组：每三人为一个小组，左边这排分为两个小组，我对面三人为一组，右边这排也分为两个小组。 &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":8175,"quote":"\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【图书介绍】\u003c/strong>（学习者场景介绍法）\u003c/p>\u003cp>今天为大家带来的书是《积极情绪的力量》，作者芭芭拉•弗雷德 里克森。\u003c/p>\u003cp>\u003cstrong>【技能点二：所选图书是实用类或理论类图书】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>步骤一【事件】\u003c/strong>\u003c/p>\u003cp>大家有没有过这样的经历？\u003c/p>\u003cp>比如阳光明媚的早晨，你一睁眼，温暖的阳光透过轻舞的白纱照射在餐桌上，你临时起意打算为家人烹制一顿美味的早餐，一骨碌爬起床，套上家居服，妆都没化就出了门，跑超市排了将近半个小时的队回到家却发现少买了两样食材；\u003c/p>\u003cp>又或者抱着减肥信条的你，天天跟自己念叨：“四月不减肥，五月徒伤悲”。结果都已经连续节食减肥两个月的你，踏上体重秤的那一刻，不但没瘦还胖了两斤。\u003c/p>\u003cp>\u003cstrong>步骤二【提问】\u003c/strong>\u003c/p>\u003cp>大家在生活或者工作中可能会遇到类似像上面的场景，当你陷入情绪的泥潭，你的第一反应是什么？懊恼自责还是烦躁不堪？？你之前的处理效果是怎样的？是不是从来没有想过要妥善处理这些情绪？\u003c/p>\u003cp>\u003cstrong>步骤三【影响】\u003c/strong>\u003c/p>\u003cp>如果不能妥善处理情绪，任由情绪失控，长此以往，不但容易伤害你与他人的关系，还容易引发各种身体疾病，比如说：耳聋耳鸣、干咳气短，严重的可能导致高血压、冠心病、胃溃疡等。\u003c/p>\u003cp>\u003cstrong>步骤四【解决】\u003c/strong>\u003c/p>\u003cp>《积极心理学》这本书通过揭示那些常常被人忽视的心理状态，来激发人们在自己的生活中开始尝试产生积极情绪，帮助人们按照自己选择的方向来掌握和驾驭生活。\u003c/p>\u003cp>下面即将学习的拆页将首先让我们了解积极情绪的十种形式。\u003c/p>\u003cp>\u003cstrong>【技能点五：学习者场景介绍法中，能够清晰辨别出事件、提问、影响和解决4个步骤。】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>希望各位学习者在跟随我完成本场第一个RIA学习之后，能够通过对比积极情绪、消极情绪和快乐情绪来描述自己所处的情绪状态。\u003c/p>\u003cp>\u003cstrong>【技能点四：学习目标中包含学习者要完成行为的具体内容和完成程度，现场学习设计清晰体现了该学习目标】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【R阅读原书拆页】：\u003c/strong>\u003c/p>\u003cp>现在让我们来阅读刚刚发到手上的原文拆页。给大家3分钟的时间阅读，阅读完的小伙伴请举手示意我。\u003c/p>","explains":"\u003cp>\u003cstrong>【I拆书家讲解引导】：\u003c/strong>\u003c/p>\u003cp>好的，我看到大部分的小伙伴已经读完了。现在我来为大家讲解一下。\u003c/p>\u003cp>\u003cstrong>【what】\u003c/strong>\u003c/p>\u003cp>首先我们来说说积极情绪的定义：\u003c/p>\u003cp>积极情绪是指个体由于体内外刺激、事件满足个体需要而产生的伴有愉悦感受的情绪。\u003c/p>\u003cp>积极情绪可细分为10种形式，包括喜悦、感激、宁静、兴趣、希望、自豪、逗趣、激励、敬佩和爱。\u003c/p>\u003cp>\u003cstrong>【对比概念强化讲解】\u003c/strong>\u003c/p>\u003cp>现在我们来列举下消极情绪的词汇：悲伤、憎恨、烦躁、厌恶、失望、自卑、自责、焦虑、愤怒、沮丧、痛苦、郁闷、伤心、难过、恨、恐惧、贪婪、嫉妒。\u003c/p>\u003cp>大家可以看到，消极情绪和积极情绪非常容易区分。\u003c/p>\u003cp>————————————————————\u003c/p>\u003cp>\u003cstrong>【穿插学习者互动】\u003c/strong>\u003c/p>\u003cp>下面我有个小小的疑问，请这位小伙伴来回答下“快乐情绪”是“积极情绪”吗？\u003c/p>\u003cp>回答：“是。”\u003c/p>\u003cp>————————————————————\u003c/p>\u003cp>好的，谢谢这位小伙伴的回答。进入讲解之前我们先来看一个例子：\u003c/p>\u003cp>\u003cstrong>【匹配例子】\u003c/strong>举一个极端的案例，比如吸毒。有位戒毒者曾经描述说他吸毒时，感觉整个身体、头部，神经都会产生一种爆发式的快感，瞬间高潮；随后两三个小时内沉浸在半麻醉状态，整个人的感觉很温暖、宁静、舒适，就像是冬日阳光洒在身体上。而心醉神迷之后，其他荡然无存，只剩下无尽的空虚。大家可以看到这种肉体上的即时快感所产生的快乐情绪更接近于消极情绪而不是积极情绪。\u003c/p>\u003cp>所以，通过这个案例，一目了然，大家可以清楚的看到，其实快乐情绪不等同于积极情绪，有时甚至更接近于消极情绪。\u003c/p>\u003cp>快乐情绪是一种感受良好时的情绪反应。那么，快乐情绪和积极情绪的区别在哪里呢？\u003c/p>\u003cp>快乐情绪通常是当下的、短暂的（甚至是瞬间的）、表面的、生理性的；它是狭隘的心理定向和即时报偿。\u003c/p>\u003cp>而积极情绪是长远的、正向的、有意义的、有影响力的、可再生的、能促进未来行动的。积极情绪所引发和扩展的心理定向可以以不同的方式在更长的时间尺度上对我们产生重大影响。\u003c/p>\u003cp>\u003cstrong>【why】\u003c/strong>\u003c/p>\u003cp>好了，现在相信小伙伴们已经对积极情绪、消极情绪和快乐情绪有了更为深刻的理解。这里我们为什么要了解情绪的种类和定义呢？\u003c/p>\u003cp>\u003cstrong>【how】\u003c/strong>\u003c/p>\u003cp>因为只有更深刻的了解情绪是什么， 在未来遭遇情绪时，才能更好的识别自己的情绪处于什么程度。\u003c/p>\u003cp>现在推荐大家一个CMR法：\u003c/p>\u003cp>1）C=Collecting：收集。收集更多的情绪词汇。\u003c/p>\u003cp>2）M=Marking:标记。捕捉情绪并给它们打上准确的标记。\u003c/p>\u003cp>3）R=Ratings：分级。学会监控情绪并为情绪分级。\u003c/p>\u003cp>\u003cstrong>【案例讲解CMR法】\u003c/strong>耶鲁大学情绪智能中心的研究显示，学校里的儿童仅仅是通过学习更多的情绪概念，就能够改善情绪管理能力，提高行为表现。其实，这个也适用于我们的日常生活。当情绪发生时，你需要知道自己经历了什么，才能把握好自己可能出现的生理、行为反应，也才能有的放矢地去应对每一种具体的情绪。你可以在发现情绪的时候，在你已有的词汇系统里面尽可能寻找贴切的词汇来形容你此刻的情绪，这个就是收集和标记的过程。然后用数字1-10给自己情绪的激烈程度打分，1表示“很轻微”，而10表示“极度激烈”。 一旦发现情绪达到6~7分，就需要注意调整自己的情绪状态。这里要提醒大家，不但要注意显性的“消极情绪”，也要注意过度的“积极情绪”可能衍生出的“消极情绪”，比如说“得意忘形”等，这就是我们要监控并为情绪分级的重要原因。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>\u003cbr>\u003c/p>\u003cp>上述的方法对于想要自我改善不断精进，着力于改善自身和他人关系的人非常有效，但是对于那种对什么都不感兴趣、随波逐流，日子得过且过，没有人生追求的人群来说并不合适。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A2催化应用】\u003c/strong>\u003c/p>\u003cp>经过刚才的讲解现在就到了我们运用三步法了。\u003c/p>\u003cp>让我们想象一下，在未来的某一天，如果遇到类似的场景：\u003c/p>\u003cp>比如说你遭遇了某事，感到自己情绪很糟，但是又说不出个所以然。你的小伙伴通过CMR法与你对话来帮助你了解你的消极情绪属于何种程度。\u003c/p>\u003cp>请各位参考上面的案例，自己编一段小剧本，注意内容要包含人物、背景和经过。\u003c/p>\u003cp>大家可以看下刚才发到手上的拆页背面的格式进行剧本编写，三分钟以后，我们请两个小伙伴合作来演绎下这个关于未来场景的小剧本。\u003c/p>\u003cp>\u003cstrong>【学习者案例：】\u003c/strong>\u003c/p>\u003cp>小杨和小园约在咖啡厅碰面，小园等了好久才看到小杨满头是汗急匆匆的坐下来点了一大杯薄荷水咕嘟咕嘟先灌了下肚。\u003c/p>\u003cp>小杨：哎呀，烦都烦死了。\u003c/p>\u003cp>小园：怎么了？来的这么晚。我看你面色好像不太好，怎么回事？\u003c/p>\u003cp>小杨：还不是因为我老公，刚又跟他吵架了。\u003c/p>\u003cp>小园：不会吧？又吵架了？能跟我说说怎么回事吗？\u003c/p>\u003cp>小杨：我跟我老公是家务平摊的，说好这周他要洗碗。结果，今天他吃完中饭就把碗一扔，电脑面前一坐“吃鸡”去了。把我给气的，把他电脑网线一剪，大吵了一架我就跑出来了。\u003c/p>\u003cp>小园：你能说说你现在什么感受吗？\u003c/p>\u003cp>小杨：还能什么感受？首先就是【心烦意乱】啊，然后觉得很【懊恼】他为什么只知道玩游戏而不顾家里的事？还觉得很【委屈】，为什么到了最后什么事都丢给我？【埋怨】他孩子也不管，家里也不收拾，只知道玩。\u003c/p>\u003cp>小园：你记得之前我们学的CMR法则吗？其实你刚刚已经准确的收集并标记了你的消极情绪了。那现在来为你的情绪做个定级，你觉得你现在的情绪处于几级？\u003c/p>\u003cp>小杨：起码得有个9级吧，不然哪里至于去剪掉他的网线啊？也许已经到了10级也说不定，我爆发出来了啊！\u003c/p>\u003cp>小园：嘻嘻，你又没有发现当我们一来二去对话过程，你已经充分运用了CMR法认识到你现在的消极情绪所处的状态啦？\u003c/p>\u003cp>小杨：你还真别说，好像真是这么回事。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}},{"id":8176,"quote":"\u003cp>在我们了解了情绪【是什么】之后，现在我们进入【怎么做】阶段——也就是今天的第二个RIA。\u003c/p>\u003cp>\u003cstrong>【技能点观察八：【A2】环节指令清晰，涵盖三级催化应用的技巧 1)学习者根据指令，设计出一个包含人物角色、有起因经过结果、有对话的故事】\u003c/strong>\u003c/p>\u003cp>第二个RIA：\u003cstrong>【学习目标】&nbsp;\u003c/strong>\u003c/p>\u003cp>希望在跟随我完成本场第二个RIA学习之后，各位学习者可以列举出将消极情绪转化为积极情绪的具体方法。\u003c/p>\u003cp>\u003cstrong>【A1量表自测】：\u003c/strong>\u003c/p>\u003cp>现在我们来做一个测试，这个测试可以让你了解自己在感知消极情绪方面的现状。\u003c/p>\u003cp>请仔细阅读发放到手中的量表，依照直觉对每一项迅速做出判断。给大家两分钟时间，大家完成之后计算下总分，并举手示意我。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>完全不符合\u003c/td>\u003ctd>偶尔符合\u003c/td>\u003ctd>较少符合\u003c/td>\u003ctd>一般符合\u003c/td>\u003ctd>比较符合\u003c/td>\u003ctd>非常符合\u003c/td>\u003c/tr>\u003ctr>\u003ctd>1\u003c/td>\u003ctd>上班路上拥堵，我会烦躁不堪。\u003c/td>\u003ctd>1\u003c/td>\u003ctd>2\u003c/td>\u003ctd>3\u003c/td>\u003ctd>4\u003c/td>\u003ctd>5\u003c/td>\u003ctd>6\u003c/td>\u003c/tr>\u003ctr>\u003ctd>2\u003c/td>\u003ctd>工作餐不合口味，我会吐槽厨师。\u003c/td>\u003ctd>1\u003c/td>\u003ctd>2\u003c/td>\u003ctd>3\u003c/td>\u003ctd>4\u003c/td>\u003ctd>5\u003c/td>\u003ctd>6\u003c/td>\u003c/tr>\u003ctr>\u003ctd>3\u003c/td>\u003ctd>帮他人代办业务，资料不全白跑一趟，我会很愤怒。\u003c/td>\u003ctd>1\u003c/td>\u003ctd>2\u003c/td>\u003ctd>3\u003c/td>\u003ctd>4\u003c/td>\u003ctd>5\u003c/td>\u003ctd>6\u003c/td>\u003c/tr>\u003ctr>\u003ctd>4\u003c/td>\u003ctd>购物结账很慢，我会很不耐烦。\u003c/td>\u003ctd>1\u003c/td>\u003ctd>2\u003c/td>\u003ctd>3\u003c/td>\u003ctd>4\u003c/td>\u003ctd>5\u003c/td>\u003ctd>6\u003c/td>\u003c/tr>\u003ctr>\u003ctd>5\u003c/td>\u003ctd>熊孩子哭闹，我会焦虑抓狂。\u003c/td>\u003ctd>1\u003c/td>\u003ctd>2\u003c/td>\u003ctd>3\u003c/td>\u003ctd>4\u003c/td>\u003ctd>5\u003c/td>\u003ctd>6\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cstrong>【I解释自测题】：\u003c/strong>\u003c/p>\u003cp>好的，我看到大家都测试完了，相信大家在测试之后一定对自己感知消极情绪方面的现状有了更深刻的了解。量表为5题，每题6分，总分30分，大家可以根据自己的各项总分加总的值，对比总分值看看自己所处的程度。\u003c/p>\u003cp>看看这边的小伙伴的分数，好的，是15分。这边的呢？嗯，是20分。\u003c/p>\u003cp>1-10分：你对消极情绪有良好的觉察能力，处于能很好处理的状态。\u003c/p>\u003cp>11-20分：属于中等状态，建议加强学习。（大多数小伙伴处于这种状态）\u003c/p>\u003cp>21-30分：你对觉察消极情绪的觉察力比较差，急需加强学习。\u003c/p>\u003cp>分值比较高，说明你容易受到消极情绪的影响，需要进行调整。那么如何进行调整呢？我们来看下面的拆页。\u003c/p>\u003cp>\u003cstrong>【R阅读原书拆页】：\u003c/strong>\u003c/p>\u003cp>大家可以阅读下发到手上的原文拆页。给大家五分钟时间，阅读完的小伙伴请举手示意我。\u003c/p>\u003cp>拆页内容：\u003c/p>\u003cp>你无法避免所有引发消极情绪的情况，就好像你每天的上下班和洗衣服、看牙医不可避免一样。如果你不能避免引发不必要的消极情绪的情况，你至少可以通过一些方法来制止它。\u003c/p>\u003cp>假设你认识到，上下班对于你的积极率是一个特别的拖累。虽然你完全可以选择远程办公,或是搬到市中心的一个离你的办公室大门只有几步之遥的公寓里，但是假如在未来的至少一年左右，长途驾车是不可避免的，那要如何改变你的情况呢?例如，你想要更多地了解什么?物理?历史?诗歌?小说?无论是什么，你都能发掘无尽的潜力，把驾驶转变成一段令人愉快的学习体验。或者，你可以找一个人来与你分享你的旅行和学习体验。或者，你可以用坐火车或公共汽车来取代自己驾驶，并且用老式的做法--捧一本书蜷缩着，或用新式的做法，这完全取决于你。\u003c/p>\u003cp>假设你发现，你在每个工作日的早餐和午餐时间里充满了焦虑，你总是吃得很匆忙，并且心里还在思考如何安排今天的事务，这里就是你要对注意力进行分配的地方了。关注吃饭的那个时刻，放下你的关于“下面做什么”的想法，以“现在是什么”取代。如果我们全神贯注的话，吃饭本身就会带来输悦和感激。将用餐的时间花在体验进食的感觉上，这样不仅化解了不必要的消极情绪，而且还释放了隐藏着的积极情绪来源。注意你选择的食物的称心味道和口感; 想一想你的食物来自哪里;想想参与到其中的农民、杂货店和厨师，他们的馈赠滋养着你。慢慢的，通过带着觉知力进食，你甚至可以减轻体重，因为你对于身体的微妙信号变得更敏感了。最重要的是，不要同时进行多种任务。你可以在用餐的之前或之后拨出时间来整理你的事务清单----在纸上或掌上设备中将它具体化，这样它就不会在你吃饭的时候侵人你的思维空间了。\u003c/p>\u003cp>我可以把“写一页半扔两页”理解成我是一个失败者，但是我也可以将它理解为我是一个作家。你可以把看牙医看做是一次痛苦的体验，或者在不过度夸大的情况下，将它看做是一次对于不适的挑战，再或者,你可以选择将它作为一种必要的保护自身健康的手段来接受。像这样的重新诠释，拔去了消极情绪的毒牙。一旦你对生活中反复出现的无端消极情绪的来源感到适应，你就会知道什么时候你最需要建立新的积极情绪。实验一下，将这些新的意义铺到你的新河床上。观察它让你感觉怎样，它如何让你平静并推动你前进。\u003c/p>","explains":"\u003cp>\u003cstrong>【I拆书家讲解引导】：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【what】\u003c/strong>\u003c/p>\u003cp>好的，我看到小伙伴差不多都阅读完了，现在来为大家做个梳理。片段涉及到“消极情绪”。我们先来为“消极情绪”做个定义：\u003c/p>\u003cp>消极情绪，它是指在某种具体行为中，由外因或内因影响而产生的不利于你继续完成工作或者正常思考的情感。\u003c/p>\u003cp>情绪没有好坏之分，消极情绪不但无法避免的，甚至有时是必要的。\u003c/p>\u003cp>\u003cstrong>【Why】\u003c/strong>\u003c/p>\u003cp>有人可能会说：“人有消极情绪有很正常啊，而且我也不觉得没处理消极情绪对我有什么影响啊？！”那是因为你可能没有意识到消极情绪对你的影响，并不代表消极情绪其实对你没有作用力，只不过你缺乏自我觉察力，没有发现罢了。消极情绪不但会损害你的人际关系，还会影响你的身体健康和幸福感。如果不懂得将消极情绪转化为积极情绪，你很可能会遭遇消极情绪对你的负面影响而不自知，反而自我感觉良好。\u003c/p>\u003cp>\u003cstrong>【HOW】\u003c/strong>\u003c/p>\u003cp>那么我们如何处理消极情绪呢？提供三个方法给大家：\u003c/p>\u003cp>\u003cstrong>【方法一：改变消极因素】：\u003c/strong>在你的能力范围内改变触发你消极情绪的因素。首先思考：“是什么引发了我的消极情绪？”\u003c/p>\u003cp>这个原因如果是个硬性条件，我能否直接“暴力消除”？所谓“暴力消除”可以理解成“有钱任性”，暴力抹杀那些触发消极情绪的因素，用钱解决问题。\u003c/p>\u003cp>\u003cstrong>【预防疑议】\u003c/strong>当然，我们这里说的有钱不是指腰缠万贯，而是指有能力用钱去解决遭遇的大多数问题。很多人会说：“问题是没钱啊！”没钱的话，就到了我们的\u003c/p>\u003cp>\u003cstrong>【方法二：植入积极要素】：\u003c/strong>\u003c/p>\u003cp>当我们无力改变现状，那么改变不了世界，只能改变自己。我们可以做一些让自己开心快乐的事情来转换自己的注意力达到调节情绪的作用。\u003c/p>\u003cp>\u003cstrong>【方法三：调整心态看待事情】\u003c/strong>\u003c/p>\u003cp>世间的事情本就无绝对的好坏之分，只在于我们看待事情的态度。所谓“塞翁失马焉知非福”。\u003c/p>\u003cp>说个我自己的案例，前年我们公司组织体检，结果发现病灶，刚被检查出来的时候，我给父母打电话：“为什么我这么倒霉，一做体检就发现自己生病要做手术！不体检就好了！”而现在做完手术恢复健康的我，非常感激那次体检，因为那次体检让我在病情还没发展成不可收拾之前就被发现了，而且手术也很成功。而后的这几年，我时常会感恩那次体检。所以当你有消极情绪时，需要你自己调整心态用积极的态度去看待。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3促动参与：微行动学习环节--引导分组讨论步骤】\u003c/strong>\u003c/p>\u003cp>大家在工作或生活中有没什么类似的烦躁事情？比如说某天突然紧张、无法集中精神、心神不宁、心情烦躁、看什么都不顺眼、就想发火，大家就想想有没有这样的情况？都是些什么事情让你如此焦虑？都是些什么时候呢？大家思考一分钟，然后我请一位小伙伴来分享一下。\u003c/p>\u003cp>\u003cstrong>【学习者案例：】\u003c/strong>\u003c/p>\u003cp>&nbsp;两天前是五一节放假的第一天，那天我跟朋友说中午去你家吃饭，然后下午去梅岭的琴社玩。结果上午正准备出门接到同事的电话说让我去加班，昨天忘记通知我了。然后我就【极不情愿】的去了单位，打电话跟朋友说我会赶快做完事情，争取两点半能出发直接去梅岭碰面。结果上午加班，高速运转，两个小时做完了以前四五个小时才能做完的事情。当时觉得情绪很【亢奋】，当时想：“早知道这样，主任你应该早点叫我来加班啊！早上八点来加班，十点就能做完走人啊！”这时我情绪还非常良好。结果挨到了下午两点正打算跟主任说我要走了，结果发现主任跑去睡觉了。等到两点半，发现主任到经理办公室回报工作去了。等啊等，等到三点半，还没出来。继续等到四点半，坏菜了，不能继续等了。我直接跟副主任说“我有事先走了啊！”等不及了，我咬咬牙还是走了。从两点我一直【焦虑】的等到了四点半，这两个多小时真是煎熬啊。\u003c/p>\u003cp>\u003cstrong>【\u003cstrong>步骤一 确定问题&nbsp;\u003c/strong>】\u003c/strong>\u003c/p>\u003cp>拆书家提问：你说的问题是 “你原本约了一个朋友去梅岭琴社，突然接到领导电话说回来加班哟。加班时候你还挺高兴自己工作效率蛮高，两个小时做了之前四五个小时才能完成的事情，原来自己爆发力挺强。结果做完了事情，想走的时候发现领导去睡觉了，结果从两点等到了四点半，期间一直焦虑煎熬。结果看到实在等不了了，就跟副主任说你得先走了。最终还是没见到主任，直接走掉了。”&nbsp;\u003c/p>\u003cp>\u003cstrong>【步骤二 确定本质 &nbsp;】&nbsp;\u003c/strong>\u003c/p>\u003cp>拆书家提问：那你觉得你这个问题的表现是什么？\u003c/p>\u003cp>学习者小周回答：焦虑、急躁。\u003c/p>\u003cp>拆书家提问：你的消极情绪是“急躁”。还有别的情绪吗？\u003c/p>\u003cp>学习者小周回答：情绪中没有“烦”这个词，只有“急”这个词。背后原因不是因为我加班，而是因为我答应了别人事情而放人家鸽子而着急。\u003c/p>\u003cp>拆书家提问：那你觉得这个事情背后的逻辑是什么？就是你“急躁”背后的逻辑是什么？\u003c/p>\u003cp>学习者小周回答：就是因为我承诺了别人要去，这样就变成了我放别人鸽子。我不想做言而无信的人。\u003c/p>\u003cp>拆书家提问：也就是说你感到烦躁的原因是因为你承诺了别人事情，因为领导加班而无法兑现你对别人的承诺，所以你感到自己情绪很焦躁。那你觉得你会产生消极情绪的本质是什么？\u003c/p>\u003cp>学习者小周回答：我没达到我期望的东西。\u003c/p>\u003cp>拆书家提问：你期望的东西是什么？\u003c/p>\u003cp>学习者小周回答：就是我期望的和现实中的差距。\u003c/p>\u003cp>拆书家提问：大家针对刚才这个小伙伴的案例，来思考下你们觉得她刚刚发生这种急躁情绪背后的本质是什么？大家可以进行下小组讨论，三分钟时间。\u003c/p>\u003cp>学习者小园回答：因为小周用了消极面去看待这个事情。这件事情其实是个很普通的事情，每个人身上都可能发生。\u003c/p>\u003cp>拆书家提问：那她自己是否发现了这个问题？\u003c/p>\u003cp>学习者小园回答：她没发现。\u003c/p>\u003cp>拆书家提问：是的，首先她自己没有发现这个问题。\u003c/p>\u003cp>学习者小园回答：她没发觉，缺乏觉察力。\u003c/p>\u003cp>拆书家提问：是的，这个就是我们刚刚说的，她没有收集和标记自己的情绪。她光急躁，除了急躁，就没别的了，她并没有深究为什么自己有了这个情绪。实际上，她可能还会有其他很多情绪，比如忧虑，担心她朋友可能不能谅解自己。或者是她思考通过什么样的方式可以缓解自己的急躁情绪。\u003c/p>\u003cp>学习者小园回答：应该是她缺乏觉察，不够了解自己所处的情绪状态。没发现自己的情绪除了急躁之后还有很多别的情绪。\u003c/p>\u003cp>拆书家提问：对，就是自我觉察力欠缺。那么还有，当她发现了自己的消极情绪，而没有采取任何措施，一直从两点急到了四点半。\u003c/p>\u003cp>学习者小园回答：是的， 她没有寻找解决方案去做，而是光等待。若她有自制力，就可以解决了。\u003c/p>\u003cp>拆书家提问：是的，她没有对自己的情绪做调整。其实自我调整的过程中，缺乏自制力。入托她有自我觉察，有自制力，发现情绪了，做好自我调整，可能当下她就去找副主任直接沟通，可能两点的时候就去找副主任做个预案：“我上午加班之前其实就约好了朋友。其实加班才是临时安排的。所以我事情做完了想提前走。”那我们可以看到，其实急躁情绪的本质是缺乏自我觉察力和自制力。\u003c/p>\u003cp>\u003cstrong>【步骤三 明确目标】\u003c/strong>\u003c/p>\u003cp>拆书家提问：那么那接下来大家来讨论下，当你发现你自己有情绪时，那你期待实现什么样的目标呢？大家花2分钟时间小组讨论，最后推选一位组长进行分享。\u003c/p>\u003cp>学习者回答：忠义难两全。要不然就打电话给朋友取消聚会，下次再聚，老老实实加班。\u003c/p>\u003cp>要不然就加完班，赶紧走人，别等那两个多小时。\u003c/p>\u003cp>拆书家提问：好的，小伙伴的目标很明确。一是你想履行对朋友的承诺。二是你想好好的完成工作，不想给领导留下玩忽职守的印象。\u003c/p>\u003cp>\u003cstrong>【步骤四 &nbsp;讨论解决方案 &nbsp;】\u003c/strong>\u003c/p>\u003cp>根据这个目标，结合刚刚讨论出的问题本质，请小组内讨论我们刚才讲的处理消极情绪的三个方法：改变消极因素、植入积极要素、调整心态看待事情。哪个方法你觉得在处理这个问题上最难？\u003c/p>\u003cp>大家可以先分组讨论然后进行投票，小组内讨论下哪个方法你觉得最难做或者最值得讨论后续的操作方法或步骤？时间是三分钟。\u003c/p>\u003cp>三分钟后。\u003c/p>\u003cp>好的，我看到各个小组表决的结果是觉得“植入积极要素”这一点比较值得讨论。\u003c/p>\u003cp>现在，大家可以提出建议看看有什么办法来“植入积极要素？”来请这边的小组分享下讨论结果。\u003c/p>\u003cp>学习者回答：当有情绪时，我们挖掘比较好的点。比如刚才小周说她四个小时的工作，两个小时就完成了。第二个就是挖掘好的点之后，深化它带来的好处。提高效率能带来成就感，帮助你成长。第三点就是通过一系列的事情，回顾之后可以产生感恩情绪。\u003c/p>\u003cp>拆书家回应式反馈：刚才大家讨论了“植入积极要素”。我觉得第一点和第二点意思相近，可以合并。所以我总结出来两点：首先，我们遇到消极情绪时，需要找到闪光点，并通过闪光点找到成就感。比如说你可以高效工作，这个就是对自己能力的肯定。其次：感恩。感恩机遇的产生，和自己抓住机会的能力。一切都是最好的安排。给你新的机会去自我觉察，抓住机会去调整自己的消极情绪，转化为积极态度去看待事情。\u003c/p>\u003cp>\u003cstrong>【技能点观察十：在未包含HOW拆页的A3环节指令清晰，学习者在拆书家主持的微行动学习环节，讨论出了这类问题的解决方案。】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【技能点观察十一：对学习者的分享和提问，有体现通过向学习者提问来进行回应式反馈】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A2催化应用-事后复盘】\u003c/strong>\u003c/p>\u003cp>相信在学完今天的拆页之后，很多小伙伴回忆起之前遇到的很多场景，突然冒头的消极情绪总会让自己低落一整天。所以事后复盘的方法可以帮助你有效的将这个拆页拆为己用。在未来的一周内，请你刻意留意自己消极情绪出现的时刻，并把自己利用CMR法处理不当消极情绪的场景记录下来。\u003c/p>\u003cp>并利用AAR复盘表进行复盘，大家可以看下发到手中的复盘表，套用里面的关键要素进行复盘。如果有不清楚的地方，可以参考复盘AAR记录表背面的举例。\u003c/p>\u003cp>在大家记录的过程中，很可能在CMR法之后，你可能会有自己细化或者精加工的想法、动作、行为，大家都可以在表上记录下来。只有经过复盘之后，才能真正的作用于将来。\u003c/p>\u003cp>\u003cstrong>【学习者案例】\u003c/strong>\u003c/p>\u003cp>AAR记录表\u003c/p>\u003cp>事件名称：与家人沟通时因误会而产生消极情绪\u003c/p>\u003cp>事件发生时间：泰国游回来之后\u003c/p>\u003cp>事件背景（用1-2句话描述）：去泰国旅游之前没有亲口告知父母自己的去向，父母是通过别的途径才了解到的。\u003c/p>\u003cp>参与者：小吴，小吴父母。\u003c/p>\u003cp>消极情绪出现的时刻：回国之后打电话给父母保平安时。\u003c/p>\u003cp>预期目标：告知父母自己平安归来，想了解父母对自己此行的想法。\u003c/p>\u003cp>实际完成情况：\u003c/p>\u003cp>打电话告诉妈妈自己已经平安归来，结果妈妈很严肃的说希望我抽空多去看望怀孕的姐姐。\u003c/p>\u003cp>CMR法的运用：\u003c/p>\u003cp>【COLLECTING】当时的消极情绪感受：忐忑、害怕、低落、不开心、内疚、羞愧。\u003c/p>\u003cp>【MARKING】标记情绪：\u003c/p>\u003cp>没有经过父母的同意就出国游玩而感到愧疚。\u003c/p>\u003cp>没有更好的关心怀孕的姐姐而内疚。\u003c/p>\u003cp>妈妈严厉说话的口气让我伤心，让我误以为她不高兴我此次出行而害怕。\u003c/p>\u003cp>此行旅游玩的很开心却没有得到家人的回应而感到心情低落。\u003c/p>\u003cp>【RATING&nbsp;】分级：给自己的情绪打分7.2分。\u003c/p>\u003cp>三步法的运用：\u003c/p>\u003cp>【方法一：改变消极因素】：下班后买好姐姐想吃的水果和零食去探望姐姐。\u003c/p>\u003cp>【方法二：植入积极要素】：探望的过程中给妈妈通视频电话，跟全家人聊天。并告诉他们此行的所见所闻，还带了很多礼物回来。\u003c/p>\u003cp>【方法三：调整心态看待事情】：聊天的过程中得知妈妈是因为下午通电话时太忙，并且很担心姐姐的身体，所以没空分享我的快乐感受，并不是反对我出国。而对家人的关心并不应该因为家人对自己行为的态度而有所改变，对家人的关心应该是无条件的爱。\u003c/p>\u003cp>\u003cstrong>【结语】\u003c/strong>\u003c/p>\u003cp>所以请大家记住今天收获到的知识点，在面对情绪时，用CMR法：收集、标记、分级来识别自己的情绪处于什么状态，并通过三步法处理消极情绪，用正确的态度面对未来。\u003c/p>\u003cp>今天的3-3练级到此结束，谢谢各位的参与。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}},{"id":8177,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1525336778000,"updated_at":1526039440000,"ria":true},{"id":4739,"topic":"给予关注并积极回应","learn_goal":"通过改变情景和视角，学会对消级情绪给予关注，积极回应","remark":"当我们处在消极情绪当中时，你很难用欣赏的眼光去看待周围发生的事情。所以当你身边的人以某种方式打破这种消极互动循环，并通过积极的方式来回应，你需要迫使自己去发现:你是不是对这个人预先做了什么假设?这种假设有没有影响你对他的行为?科学研究已经证明:积极回应要远胜于恶意回应，关注与积极投入才能让彼此关系有长足发展。所以，通过改变情景和视角向那些正在遭受痛苦的人提供同情心，爱心和开放性，不对他们抱有敌意才能在彼此消极的情绪中解放出来。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"船长（魏云）","city":"南昌"},"club":{"name":"南昌滕王阁分舵","city":"南昌"},"prologue":"大家好，我是拆书帮分舵南昌滕王阁会员——魏云，曾是一名幼教工作者。喜欢孩子，喜欢阅读。一直不满足于现状的我，对学习的不同形式充满渴望，正是这种渴望把我带到了这里和你们在一起。为此，感到非常荣幸。想从三个方面标签一下自己（个性方面）如果用一种动物来形容自己，我希望是——长颈鹿。平静，理智，包容是我想要成为的理想状态。（工作方面）喜欢和孩子在一起，静静感受他们的美好。（生活方面）重心就是找\r\n那“缺失的一角”虽然因为这些缺失，人生的道路走的很慢，但我会努力寻找并勇往直前. \r\n拆书不是把书中的知识拆为碎片，而是找到你需要的重点予以实践。在这里我们强调以学习者为中心，而不是以知识为中心。我们有两种学习法，个人学习的应用是——便签法，即让人读一本书就能达到参加同主题培训的效果；而组织学习的应用是一位拆书家拿一本书加工出一场现场学习，通过RIA流程引导和促进一群人把知识拆为己用，所以这是一个基于拆书法的学习爱好者社群。我们的拆书帮分舵遍布全国，是一个公益性的青年自发组织。如果你是一个学习爱好者，欢迎加入我们！如果你已加入拆书帮，请相信这里会帮助你成长为一个有温度，有能量的实践者，从而去帮助更","ratings_count":1,"texts":[{"id":7814,"quote":"\u003cp>片段一：改变视角\u003c/p>\u003cp>。\u003c/p>\u003cp>片段二：改变情景\u003c/p>","explains":"\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 当我们处在消极情绪当中时，你很难用欣赏的眼光去看待周围发生的事情。所以当你身边的人以某种方式打破这种消极互动循环，并通过积极的方式来回应，你需要迫使自己去发现:你是不是对这个人预先做了什么假设?这种假设有没有影响你对他的行为?科学研究已经证明:积极回应要远胜于恶意回应，关注与积极投入才能让彼此关系有长足发展。所以，通过改变情景和视角向那些正在遭受痛苦的人提供同情心，爱心和开放性，不对他们抱有敌意才能在彼此消极的情绪中解放出来。\u003c/p>","interaction":"\u003cp>&nbsp;&nbsp;&nbsp; 想到前不久的一个晚上，当时9点多了，一直催促着刚写完作业的孩子洗洗睡睡，好让自己把他们班环境布置的任务完成。正在为孩子的磨磨蹭蹭烦躁不已，突然就感觉到整个房子都震动了起来，当然不是拆迁，也不是地震，而是让我脑袋轰鸣的机床在工作。当时真心想对楼上狂喊:“讨不讨人厌，做你邻居的真是倒霉！”但考虑到那是自己老公，也不想让他在邻居前没脸，所以就打了一通电话过去，生气的说:“都什么时候了，你知道那个机器有多吵吗？我还能做事吗？你还让儿子睡觉吗？你考虑过你邻居的感受吗？你怎么这样呀！”发了顿牢骚，没听他说什么，就挂了电话。可还没一会儿，又听到了轰隆声，简直绝倒。当我想冲上去吵一架的时候，他不声不响的就下来了，手上拿着些东西，问我这个可以吗？当时瞬间就无语了，我感觉自己突然从消极的情绪中解放了出来。只因为下午无意识的抱怨了一句想做照片墙却找不到材料，而他给我的正是一个精美的相框架。一直以来我都觉得他是个甩手爸爸，从没指望他能帮忙，但这一次他的行动打破了我们在共同教育孩子这一方面的消极循环。让我不禁要重新反思自己一直以来对他的各种抱怨、消极态度与看法。\u003c/p>\u003cp>通过这件事也让我有勇气面对很多我们日常生活情景当中的消极源。比如针对在家里每天清晨一起床对孩子的数落和催促，我可以制定一个每日计划清单（按时间顺序）:\u003c/p>\u003cp>☆七点起床，穿衣，叠被。\u003c/p>\u003cp>☆刷牙，洗脸，搽香。\u003c/p>\u003cp>☆营养早餐（五谷杂粮，蔬果汤粥，牛奶鸡蛋）\u003c/p>\u003cp>☆上学出行必备:书包，水，篮球，校服，红领巾。\u003c/p>\u003cp>☆课堂举手发言3～5次，并反馈老师的课堂提问。\u003c/p>\u003cp>☆完成课堂笔记，内容清晰整洁。\u003c/p>\u003cp>☆给予家人，朋友或师长每天3~5个拥抱，和10个微笑。\u003c/p>\u003cp>☆作业能做到提笔即是练字时，并按笔顺规则写字。\u003c/p>\u003cp>☆完成家联本上的作业并签字。\u003c/p>\u003cp>☆课外阅读，并大声朗读20分钟。\u003c/p>\u003cp>☆篮球体能训练三项\u003c/p>\u003cp>☆8:45洗漱，9:00上床。\u003c/p>\u003cp>☆分享睡前故事10～20分钟，关灯睡觉。\u003c/p>\u003cp>为每天完成度打分，连续完成一周，可以答应孩子一个合理的要求。\u003c/p>\u003cp>对于老公的抱怨和不认同，我想做出以下改变:\u003c/p>\u003cp>1、老公在谈话时给予倾听与回应，可以适当联系自己感兴趣的话题，不时的问问他的看法。\u003c/p>\u003cp>2、没事就和孩子上楼参观一下他的工作坊，问一些自己感兴趣的问题，还可以跟着学一学。并对他的手工活给予肯定，不时的在朋友圈晒一晒。\u003c/p>\u003cp>3、看到关于木工活的书买一些，送给他。\u003c/p>\u003cp>4、遇到问题可以适当的求助他，尤其在他擅长的领域。\u003c/p>\u003cp>5、避免出现消极对话，尽可能的以中性或积极的方式回应。\u003c/p>\u003cp>6、通过拆书练习，多反思自己的行为。\u003c/p>\u003cp>我希望执行这些行动计划至少3个月，以便能融入我们的生活中成为习惯。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1520314655000,"updated_at":1520676197000,"ria":true},{"id":2131,"topic":"怎么体会积极的情绪","learn_goal":"学会表达RIA便签","remark":"要想获得完满的人生，你必须借助积极情绪的力量。积极情绪会扩展我们的思维和视野，建构帮助我们成功的各项资源。积极情绪为我们带来健康，让我们更加坚韧，并抑制无端的消极情绪。最重要的是，我们都可以通过努力来提高自身的积极情绪。","level":"TF1-1","duration":12,"status":0,"type":0,"chaishujia":{"username":"上善若水","city":"西宁"},"club":{"name":"兰州金城关分舵","city":"兰州"},"prologue":"各位拆书家各位小伙伴们大家好！我叫王蕾，是一名培训师，我平时比较喜欢看书、听音乐还有旅行。我的人生格言是：一切都是最好的安排，要勇于活在当下。而现在我要做的就是成为一名真正的拆书家。我的学习心得是每天进步1%，那么100天我的进步就会是100%。我最想要的事，是在未来遇见最好的自己。关于什么是拆书？什么是拆书帮？我将通过以下几个方面进行介绍：拆书是一种读书的方法论，是关于成人学习的方面论，它提倡通过学习改变行为，践行把图书的知识转化为你自己的能力，所以所谓拆收不是拆散而是转化。拆书培养通过读书创造价值的能力，或把知识转化为能力的能力，这是一种全新的学习形式。拆书可分为个人学习的拆书和组织学习的拆书法，个人学习的应用是RIA便签读书，让人读一本可以达到参加一场培训的效果；组织学习的应用是一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。那么拆书帮，就是这样一个公益性组织，提取总结书中的能量，再把精髓分享给所有爱好读书的人们。","ratings_count":0,"texts":[{"id":4781,"quote":null,"explains":"\u003cp>大家会不会有这样一种体验呢？就是当你不开心的时候，你会发现周围一切都不开心，每件事情的发生都不合你的心意，你对周围发生的每一件事情都提不起半点兴趣，而且如果你刚好在做一些事情，你会发现你因为心不在焉总是出错，而越是出错你的情绪就越差，越消极，这样循环往复变成了恶性循环。其实有些事情发生了，我们也没有办法去避免，但是我们可以换一种思维，换一种心态去考虑，这样事情往往会朝着好的方向发展。今天我带给大家一本我个人非常喜欢的书箱之一《积极情绪的力量》第55页中的一个片断，希望大家阅读过后，都可以学会用积极的情绪来面对消极的事情。这本的书的作者是芭芭拉.费雷德里克森，她是积极心理学领域的天才，是享誉全球的最杰出的积极情研究者，她的书不仅强调了积极情绪的意义，同时也肯定了消极情绪的力量，她教会我们如何能产生积极情绪，也告诉我们如何通过练习实践来提高我们的积极情绪。\u003c/p>\u003cp>通过刚刚的阅读，书中提示我们积极情绪的产生是由你对事件如何解释而来的，积极情绪的产生取决于，当我们发生一件事情的时候，我们会花一些时间来发现其实事物都有好的一面，而且我们还会把好的一面发展成来好的结果。我们打开积极的情绪，就自然关闭了消极的情绪，所以我们怎样产生更多的积极情绪，而源于我们对待每件事物的思考。\u003c/p>","interaction":"\u003cp>我是一个标准的上班族，每天早晨会乘坐公交车到公司上班，但是坐车上班成为我每天一早的魔咒。为什么会这样说呢？因为我人每天早晨都会在相同的车站坐车，坐相同的车停靠在相同的每一站，在上班高峰期间，上班族、学生和晨练的老人们都会拼命想尽办法挤上公交车，所以每到一站他们都会紧紧扒住车门，让车子无法起动，每站司机是师傅都会重复相同的话。每天每天都一样，看到的景色，听到的话，让我深深地郁闷了，这种消极的情绪一直都会延续到我的工作中，有时想想早晨挤车的经历心情就很低落。\u003c/p>\u003cp>\u003cstrong>积极情绪的产生就像所有情绪一样，源于你对事物是如何解释的。它们取决于你是否允许自己花一点时间来发现事物的好的方面，同时还取决于你是否允许自己给它们打气并让它们成长。\u003c/strong>\u003c/p>\u003cp>积极情绪的产生是取决于我对事物的看法，今天早晨我像往常一样的时间出门坐车，临走时随手拿了最近我一直在阅读的书，（我家附近的车站本就离终点不远，因此我可以坐到坐位去上班。）上车后我找在位子坐下，准定了时间，但翻开书开始看起来，过一段会看看时间和站点，没想到平时感觉漫长到不行的时间，居然很快就过去了，没看几章我就到公司站点下车了。回想一下，今早的心情很舒服，好像把魔咒破解了的轻松感，头脑很清醒，感觉利用坐车的时间来做了有效率的事情。从今天起以后每天我都会为自己准备一本书，或是利用乘车的时间来做些自己喜欢做的事情。原来积极的情绪真的取决于我们对待事物的解释，能否体验到积极情绪，取决于我是如何思考的。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1489318064000,"updated_at":1489318064000},{"id":666,"topic":"觉知力、主动行善","learn_goal":"学习者能够明白通过\"修炼觉知力\"和\"主动行善帮助他人\"可以提","remark":"","level":"TF3-3","duration":60,"status":0,"type":0,"chaishujia":{"username":"向军","city":"南昌"},"club":{"name":"南昌滕王阁分舵","city":"南昌"},"prologue":"图书介绍 \r\n 《积极情绪的力量》的作者芭芭拉•弗雷德里克森，是美国北卡罗来纳大学的教授，国际上著名的研究积极心理学的领军人物。\r\n 这本书得到了积极心理学之父马丁•塞利格曼、心流之父希斯赞特米哈伊、情商之父丹尼尔•戈尔曼，三大巨头的联合推荐。这本书由湛庐文化出品，中国人民大学出版社出版。 \r\n 积极情绪会扩展我们的思维和视野，建构帮助我们成功的各项资源。这是一本教我们追寻幸福的书，作者通过多年的研究告诉我们，我们可以通过7种方法降低消极情绪、11种方法提升积极情绪，最终实现美好的人生。\r\n一、【A1】请大家自测\r\n 请大家阅读下面的4个测试题，根据自己的实际情况打分（0分表示：完全不符合自己的实际情况，5分表示：非常符合），然后把4项得分相加，算出总分。\r\n1、当遇到某事不顺时，我会产生消极想法，但我会意识到它只是一个想法，不会让它轻易的影响到我的情绪。\r\n 0 1 2 3 4 5 \r\n2、我明白“修炼觉知力(冥想","ratings_count":0,"texts":[{"id":2051,"quote":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u003cstrong>方法3：\u003c/strong>\u003cstrong>变得更有觉知力\u003c/strong>\u003cstrong>\u003cbr> \u003cbr> \u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp;&nbsp;&nbsp; 你的习惯性思维是河床，你的情绪是河流。消极思维必然会产生，然而这时消极情绪往往一涌而出，似乎在你的控制之外。消极思维能够发展出一长串的联系，用讨厌的消极情绪填充你的脑海。拦截住这个涌流——抑制住你的消极情绪，就显得很诱人。但是科学表明，\u003cstrong>企图阻断消极思维和消极情绪的尝试会适得其反\u003c/strong>。抑制并不能降低讨厌的消极情绪，反而会加倍你心理上、肉体上和思维上的痛苦。也许与人们的直觉相悖，\u003cstrong>对消极情绪保持开放性，要比把它挡在外面更健康\u003c/strong>。另一种经科学检验用来遏制消极情绪势头的方法是\u003cstrong>修炼觉知力\u003c/strong>。\u003c/p>\u003cp>&nbsp; &nbsp;&nbsp;&nbsp; 在佛教中，用来发展\u003cstrong>念力\u003c/strong>（觉知力）的冥想练习已经经过了数百年的积累。许多人把佛教看做是来自东方文化的一种宗教或精神修炼。然而，西方的科学家，包括我自己，逐渐把它看做更多的东西。鉴于它细致地描述了\u003cstrong>人类思维如何运作\u003c/strong>以及我们如何才能有意识地\u003cstrong>将思维训练得更健康、更快乐\u003c/strong>，\u003cstrong>佛教\u003c/strong>也是一门真正意义上的\u003cstrong>心理学\u003c/strong>。\u003c/p>\u003cp>&nbsp; &nbsp;&nbsp; 乔恩·卡巴金是在20世纪80年代初期，从古老的佛教修炼中将觉知力心理学精选出来的第一位西方科学家，他还把它教给波士顿地区的医疗患者。他把这项成果称为“\u003cstrong>正念减压疗法\u003c/strong>”（MBSR），并给了他的患者一个关于觉知力的简单定义：“\u003cstrong>觉知力\u003c/strong>意味着\u003cstrong>以一种特定的方式保持注意——关注目标，在当前的时刻，不带任何评价\u003c/strong>。”变得更有觉知力，然后，以完全的意识并不加评判地关注你自己的内心体验。在心理上，你从思维和感官的溪流中后退一步，获得对于你的思维的更广泛的视角。在实践上，你要学会\u003cstrong>用一种不反应的方式冷静地观察你的思维内容\u003c/strong>。你要学会\u003cstrong>把一个想法就当做一个想法来接受：这仅仅是发生在你脑海中的一个事件，它的产生、形成和经过就像天空中的云朵一样，很快地消散了\u003c/strong>。在觉知的状态中，你更有可能接受一个人的想法——哪怕是消极的想法——而\u003cstrong>无需在情绪上按照它们行事或对它们作出反应\u003c/strong>。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;\u003cstrong>觉知力的力量\u003c/strong>在于\u003cstrong>，它可以从根本上切断消极思维和消极情绪之间的联系\u003c/strong>。当你学会\u003cstrong>将一个消极想法仅仅当做一个想法来接受\u003c/strong>时——也就是\u003cstrong>会随着时间而过去\u003c/strong>——你就消除了它。认识到消极思维和消极情绪是相辅相成的，你就能够选择不要前往那里。你可以接受一个消极的想法，同时选择不去放大它。\u003c/p>\u003cp>&nbsp; &nbsp;&nbsp; \u003cstrong>觉知是一种技能。它并不是天生的\u003c/strong>。就好像学习弹钢琴或是打网球，它需要教学和实践。这是佛教修炼和卡巴金模型中共有的观点。觉知力的正式培训现在已经积累了让人惊叹的记录。大量的科学研究证实了开展觉知力的练习给身心健康带来的好处。科学也证明，\u003cstrong>觉知力训练给大脑留下了持久的印记。它改变了支持着情绪反应的大脑回路的基本代谢，降低与消极情绪有关的回路的活动，并增加与积极情绪有关的回路的活动\u003c/strong>。这意味着你可以有意识地\u003cstrong>改变大脑的工作方式\u003c/strong>——你可以利用神经可塑性来移动自己的情绪河床。\u003c/p>","explains":"\u003cp>&nbsp;&nbsp;大家在看了这个原文片段后，请说出给你印象最深刻的一句话或一个关键词。\u003c/p>\u003cp>……\u003c/p>\u003cp>\u003cstrong>学习者01： ”\u003c/strong>佛教也是一门真正意义上的心理学”，其实心理学和哲学都是从宗教引申出来的。\u003c/p>\u003cp>\u003cstrong>学习者02：“\u003c/strong>对消极情绪保持开放性，要比把它挡在外面更健康”，很多大人不接受孩子的哭泣，当孩子哭泣时，一些大人会去斥责、嘲笑，结果让孩子更加痛苦。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 消极思维会引发消极情绪，消极情绪又会助长消极思维。为了不受消极情绪的困扰，我们有时会直接去阻断消极思维。打个比方说，有些人会为童年发生的一些创伤一直耿耿于怀，这是一种消极思维。这种消极思维会引发消极情绪，会让人感到痛苦、悲伤。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 而以正念的方法应该怎样应对呢？\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 按照书中的原文，第三自然段的第6行“我们可以用一种不反应的方式冷静地观察我们的思维内容”，也就是说，观察你自己的思维，而不带任何评价，这种方法能够减轻你的痛苦。也就是说，接纳当下发生的一切，顺其自然，保持正念。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;有的人可能会说：“‘顺其自然’是不是什么事都不作为呢？”\u003c/p>\u003cp>不是的，真正的保持正念、顺其自然，并不是两手一摊的不作为，而是全力以赴后的不强求。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;做正念冥想有什么好处呢？\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 可以让我们不被情绪、想法影响，具体有以下3点好处。\u003c/p>\u003cp>1.始终保持头脑清醒、专注、平静的心理状态\u003c/p>\u003cp>2.减轻压力、保持平和的心态，让身体更加健康\u003c/p>\u003cp>3.活在当下，提升我们当下的幸福感。\u003c/p>","interaction":"\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>A1\u003c/strong>\u003cstrong>】激活经验\u003c/strong>\u003cbr>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 大家在平时的生活中，有没有以下3种情况：\u003c/p>\u003cp>1.感觉自己没有价值，经常感到很难过，闷闷不乐，觉得这个世界没有希望了。\u003c/p>\u003cp>2.有时会被别人做的某件事，或被别人说的一句话，突然变得暴跳如雷。\u003c/p>\u003cp>3.经常做事像丢了魂一样，整天浑浑噩噩，一天下来自己都不知道自己在干嘛？\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;或者还有其他在生活中经常让你感到烦恼、焦虑的事。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 请每人先在纸上写下你想分享的故事中的关键词，然后在小组内开始讨论分享。5分钟后，我会请几位代表来分享一下。\u003cbr>\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>&nbsp;\u003cbr>\u003c/p>\u003cp>\u003cstrong>学习者01：&nbsp;\u003c/strong>有好几次，早上上班出门走在半路中，突然想起有什么东西忘记拿，于是又赶回去，匆匆忙忙拿了东西出来，突然想起好像忘了锁门，于是又回云锁门。哎，做事跟丢了魂一样。\u003c/p>\u003cp>\u003cstrong>学习者02：&nbsp;\u003c/strong>当别人批评我们带有人身攻击时，我会突然暴跳如雷。\u003c/p>\u003cp>\u003cstrong>学习者03：&nbsp;\u003c/strong>一件事情没处理好，感觉很烦，正好孩子又来找我玩，那就更烦了。\u003c/p>\u003cp>\u003cstrong>四、【\u003c/strong>\u003cstrong>A3\u003c/strong>\u003cstrong>】促动参与\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 现在，我们来做一个正念练习，首先请每个人集中注意力，现在，每人开始在脑海里想一件近期让你感到烦恼或者焦虑的事情，然后请大家根据音乐的提示来做，这段音乐主要分为3个部分，第一个部分的是集中注意力观察你自己有哪些想法、感受、身体感觉。第二个部分是集中注意力关注你的呼吸。第三个部分是关注你的全身。\u003c/p>\u003cp>这段音乐大约有4分钟，在这4分钟之内，请大家闭上眼睛不要说话。好的，现在正式开始：\u003c/p>\u003cp>请大家发表一下感想\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>&nbsp;\u003cbr>\u003c/p>\u003cp>\u003cstrong>学习者01：\u003c/strong>在做冥想的过程中，我感受到负面情绪时，就把呼吸带到感觉难受的那个部位。\u003c/p>\u003cp>\u003cstrong>学习者02：\u003c/strong>我觉得做冥想有3个好处，一个是放空，把负面情绪思想放空。\u003c/p>\u003cp>第二个是关注，关注内心的情感，关注自己的身体。\u003c/p>\u003cp>第三个是升华，让自己找到学习的方向。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":2052,"quote":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;&nbsp; &nbsp;\u003cstrong>方法5：\u003c/strong>\u003cstrong>计算善意\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp;善意至少有两个方面：当你计算你的福气时，你常常会赞赏别人对你是如此的友善，这引起了你的\u003cstrong>感激\u003c/strong>之情；而在实验中，我们认识到善意的另一面——另一个提高你的积极情绪、却简单而不费成本的方式，当我的合作者与我要求“被试”更多地\u003cstrong>意识到自己对别人的善意\u003c/strong>，并对每一个善意的举动都保持日常的统计时，他们的积极情绪大大地提高了。这种“计算善意”的干预措施似乎是有效的，因为欣欣向荣的人们更习惯于表现善意、关注他人，对于善意如何能够发挥积极的作用更加敏感。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003cstrong> \u003c/strong>\u003cstrong>&nbsp;\u003c/strong>\u003cstrong> \u003c/strong>\u003cstrong>善意\u003c/strong>和\u003cstrong>积极情绪\u003c/strong>相辅相成\u003cstrong>。只要认识到自己的善意举动，就能够启动这种良性循环。\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp; 发展—种眼光来欣赏你自己的善意只是一种心理转变，你会注意到它更多的方面。你能够通过增加你的善意举动，使你的积极情绪大幅提升。实验表明，\u003cstrong>有意识地增加你的善意\u003c/strong>可以\u003cstrong>提升你的积极情绪\u003c/strong>。但是同样的，这里有一个关于时机的告诫。每星期在单独的―天里做几件大好事会很有帮助，而把它们分散在整个星期当中则不然。不要感觉这是例行公事或是司空见惯，要让你的善举新鲜和不平凡，创建一个固定的“\u003cstrong>善意之日\u003c/strong>”能够帮助你做到这一点。这样会让你维持在一般日子里对于善意的一般表达，但是选择特定的一天来将之提高到一个高得多的水平。这可能就是为什么专门用一天或一个下午来做志愿者工作，无论是每周一次或是每月一次，都能够产生很多的积极情绪的原因。这可能也是为什么科学研究表明，\u003cstrong>帮助他人\u003c/strong>能预示\u003cstrong>长寿\u003c/strong>的原因。\u003c/p>","explains":"\u003cp>&nbsp;大家在看了这个原文片段后，请说出给你印象最深刻的一句话或一个关键词。\u003c/p>\u003cp>……\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 善意，包括两个方面&nbsp;\u003c/p>\u003cp>1.当我们对别人的善意表示感恩时，这能够提升我们的积极情绪。\u003c/p>\u003cp>2.当我们主动行善帮助别人时，能够大幅度地提高我们的积极情绪。\u003c/p>\u003cp>也就是说，无论是接受还是付出善意，都能够提升我们的积极情绪。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;而且最关键的是善意和积极情绪是相辅相成的。这句话怎么理解呢？\u003c/p>\u003cp>有谁能够解释一下吗？……\u003c/p>","interaction":"\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>A1\u003c/strong>\u003cstrong>】激活经验\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 每个人在生活中都应该做过善事帮助过别人，现在我请大家回忆一下，给你印象最深刻的一次你主动帮助别人的事件，请分享一下事件的经过以及你当时的感受。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;请大家在小组内分享一下，请组长用纸笔记录一下每个人说的例子，并在小组讨论后概括的说一下。小组分享的时间是5分钟。 &nbsp; &nbsp;\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003cbr>\u003c/p>\u003cp>\u003cstrong>学习者01：\u003c/strong>我在的幼儿园有一名老师，他刚来幼儿园工作的时候呢，普通话说话不标准，在工作上也遇到很多困难，使得她经常很消沉。我看到后，就经常去帮助她，帮她纠正普通话发音，在生活上关照她。慢慢的，她就改变了。后来她成为幼儿园里表现最好、工作最积极的一名老师。每当我回想起我做的这件好事，我心中就会涌动出一股成就感。\u003c/p>\u003cp>\u003cstrong>学习者02：\u003c/strong>在我很小的时候，我记得是上一年级，有一天放学回来，在路上遇到一个老人在乞讨，他看上去很饿的样子，我就把包里所有的零食都给了这位老人家吃。我当时的感受是觉得很自豪，很快乐。\u003c/p>\u003cp>\u003cstrong>\u003cstrong>四、\u003c/strong>【\u003c/strong>\u003cstrong>A2\u003c/strong>\u003cstrong>】催化应用\u003c/strong>&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;在明白了善意和积极情绪的关系后，你将会在今后的生活中，如何通过接受善意感恩他人，付出善意帮助他人，来提升自己的积极情绪呢？\u003c/p>\u003cp>请大家先在小组讨论一下，找到最适合自己的方式，然后每人写在一张便签纸上。 &nbsp;&nbsp;\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>&nbsp;\u003cbr>\u003c/p>\u003cp>\u003cstrong>学习者01：\u003c/strong>我打算在8月17号到8月23号去赣州做儿童心理义工助教，我准备把我会的很多互动游戏都教给他们。\u003c/p>\u003cp>\u003cstrong>学习者02：\u003c/strong>我准备在明年继续资助两名失学儿童，一直资助到他们读完大学为止。\u003c/p>\u003cp>\u003cstrong>结语：\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;&nbsp;今天我们学习了减少消极情绪、提升积极情绪的两种方法：第1个是&quot;修炼觉知力&quot;，也就是培养正念，这种方法可以减少消极情绪，并提升我们对积极情绪的敏感度。第2个是接受善意感恩他人，主动行善&quot;帮助他人&quot;，这样可以直接提升我们的积极情绪。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 这两种方法都能够让我们变得更快乐更长寿。希望大家在以后的生活中多多实践，活出自己的幸福生活。\u003c/p>\u003cp>\u003cbr>\u003cbr>\u003cstrong>布置任务：\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;请大家在回去的一个月内，找机会和自己身边的亲人朋友，谈谈正念冥想、积极行善帮助他人可以带给我们的好处，帮助我们身边的人，帮助我们爱的人提升他们的积极情绪，从而提高幸福快乐的能力。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1470025754000,"updated_at":1470025754000,"ria":true}]};